{id:39,c:'st',t:'Làm một món quà handmade để tặng',n:'Món quà tự làm có thể vụng, nhưng không bao giờ vô tâm.',s:'Chọn một thứ dễ làm như thiệp, vòng tay hạt, khung ảnh. Tìm video hướng dẫn và xem nhà có sẵn vật liệu gì.',p:90,k:1,ai:'abyg',o:'i',g:'sct',m:'cbl',d:4},
{id:40,c:'st',t:'Trồng một chậu rau thơm',n:'Chăm một mầm cây lớn lên từng ngày là liều thuốc chữa sốt ruột.',s:'Mua một chậu nhỏ, đất và hạt rau mùi hoặc húng, gieo xong đặt chỗ có nắng sớm.',p:45,k:1,ai:'ag',o:'b',g:'sc',m:'bcx',d:2},
{id:41,c:'st',t:'Viết một truyện ngắn 300 chữ',n:'Trong đầu ai cũng có một câu chuyện. Hôm nay cho nó ra giấy.',s:'Bắt đầu bằng câu “Hôm ấy trời mưa, và tôi gặp lại…”, rồi viết tiếp 15 phút không dừng.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'cbl',d:4},
{id:42,c:'st',t:'Nhờ AI viết một bài hát về bạn',n:'AI không thay được bạn, nhưng có thể giúp bạn nhìn mình theo một cách mới.',s:'Mở công cụ AI bạn đang dùng, tả bản thân bằng 5 từ và nhờ nó viết lời một bài hát vui.',p:20,k:0,ai:'aby',o:'i',g:'sctk',m:'ch',d:1},
{id:43,c:'st',t:'Bày lại góc phòng theo kiểu mới',n:'Đổi chỗ cái bàn, căn phòng thành mới. Đôi khi tâm trạng cũng vậy.',s:'Chọn một góc, dọn hết đồ ra, chỉ đặt lại những gì thật sự dùng và thêm một thứ bạn thích nhìn.',p:90,k:0,ai:'ag',o:'i',g:'sct',m:'cbx',d:4},
{id:44,c:'st',t:'Làm một cuốn album ảnh in',n:'Ảnh trong điện thoại rồi sẽ trôi mất. Ảnh trên giấy thì ở lại.',s:'Chọn 20 tấm đẹp nhất năm nay, mang ra tiệm in, dán vào sổ và ghi vài dòng dưới mỗi tấm.',p:120,k:1,ai:'abyg',o:'b',g:'sc',m:'bl',d:4},
{id:45,c:'st',t:'Tập viết chữ đẹp 20 phút',n:'Viết chậm lại một chút, chữ đẹp lên và lòng cũng tĩnh hơn.',s:'Lấy bút dạ hoặc bút lông, xem một video lettering cơ bản rồi tập viết tên mình 20 lần.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'bx',d:3},
{id:46,c:'st',t:'Viết 8 câu rap hoặc thơ về tuổi của bạn',n:'Tuổi 20, tuổi 30 của bạn đáng được kể bằng giọng của chính bạn.',s:'Bắt đầu bằng “Năm nay mình…”, viết 8 câu, cố gắng để các câu cuối vần với nhau.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'cbx',d:5},
{id:47,c:'st',t:'Chụp một bộ ảnh chân dung cho bạn thân',n:'Ai cũng đẹp khi được nhìn bằng con mắt thương mến.',s:'Hẹn bạn lúc 16–17 giờ khi nắng dịu, chọn một bức tường đẹp và chụp ít nhất 50 tấm.',p:90,k:0,ai:'by',o:'o',g:'c',m:'chl',d:3},
{id:48,c:'st',t:'Vẽ lại một chiếc áo hoặc đôi giày cũ',n:'Món đồ cũ cộng chút sáng tạo thành món đồ không ai có.',s:'Chọn một món sắp bỏ, mua màu vẽ vải, phác ý tưởng lên giấy trước rồi mới vẽ.',p:120,k:1,ai:'ab',o:'i',g:'sct',m:'ch',d:5},
// —— Học hỏi
{id:49,c:'hh',t:'Đọc 30 trang sách',n:'Mỗi ngày 30 trang, 10 ngày là xong một cuốn. Và bạn đã khác đi một chút.',s:'Lấy cuốn đang đọc dở hoặc mượn một cuốn, đặt hẹn giờ 30 phút và úp điện thoại xuống.',p:40,k:0,ai:'a',o:'b',g:'sctk',m:'cbmxl',d:3,ch:1},
{id:50,c:'hh',t:'Học 20 từ tiếng Anh về công việc của bạn',n:'20 từ hôm nay, 600 từ sau một tháng. Tiếng Anh không khó, chỉ cần đều.',s:'Viết ra 20 thứ bạn làm hoặc thấy mỗi ngày ở chỗ làm, tra từ tiếng Anh và đặt một câu với mỗi từ.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:3,ch:1},
{id:51,c:'hh',t:'Xem video “một ngày làm nghề X”',n:'Muốn biết mình hợp nghề gì, hãy xem tận mắt người ta làm nghề đó.',s:'Gõ “a day in the life of” kèm một nghề bạn tò mò lên YouTube và xem 2 video.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'c',d:1},
{id:52,c:'hh',t:'Học một hàm Excel: XLOOKUP hoặc Pivot',n:'Kỹ năng nhỏ mà tiết kiệm cho bạn hàng giờ mỗi tuần.',s:'Mở một file dữ liệu bất kỳ, tìm video hướng dẫn 10 phút và làm lại theo từng bước.',p:45,k:0,ai:'a',o:'i',g:'sct',m:'ch',d:4},
{id:53,c:'hh',t:'Học xong bài đầu của một khóa online miễn phí',n:'Bài đầu tiên là bài khó bắt đầu nhất. Phần còn lại chỉ là thói quen.',s:'Chọn một nền tảng học trực tuyến có khóa miễn phí, đăng ký một chủ đề bạn tò mò và học xong bài 1 hôm nay.',p:60,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:4},
{id:54,c:'hh',t:'Nghe một podcast về chủ đề bạn chưa biết gì',n:'Não thích điều mới. Hôm nay cho nó nếm một món lạ.',s:'Mở ứng dụng podcast, chọn một chủ đề thật lạ như thiên văn, lịch sử hay tài chính, nghe lúc đi bộ hoặc rửa bát.',p:45,k:0,ai:'a',o:'b',g:'sctk',m:'cbm',d:1,ch:1},
{id:55,c:'hh',t:'Nhờ AI lập lộ trình học 30 ngày',n:'Mục tiêu mơ hồ thì mãi mơ hồ. Chia nhỏ ra là thành việc làm được.',s:'Viết cho AI: “Mình muốn học [kỹ năng], mỗi ngày có 30 phút, lập lộ trình 30 ngày”. In ra và dán lên tường.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:2},
{id:56,c:'hh',t:'Học 10 câu giao tiếp một ngoại ngữ mới',n:'Chào được ai đó bằng tiếng mẹ đẻ của họ là cách nhanh nhất để thấy họ cười.',s:'Chọn tiếng Hàn, Nhật, Trung hay bất kỳ tiếng nào, tìm video 10 câu cơ bản và nói to theo mỗi câu 5 lần.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:3},
{id:57,c:'hh',t:'Tìm hiểu tên con đường nơi bạn sống',n:'Con đường bạn đi mỗi ngày có thể mang tên một người đã làm nên lịch sử.',s:'Tra tên đường, tên xã hoặc phường của bạn, hoặc hỏi người già trong xóm xem cái tên ấy có từ đâu.',p:30,k:0,ai:'ag',o:'b',g:'sctk',m:'cl',d:2},
{id:58,c:'hh',t:'Xem một bộ phim tài liệu',n:'Một tiếng rưỡi là bạn đã tới đáy đại dương hoặc đỉnh Everest.',s:'Chọn một phim tài liệu được đánh giá cao trên nền tảng bạn đang dùng và xem hết không tua.',p:90,k:0,ai:'ayg',o:'i',g:'ctk',m:'cmb',d:1},
{id:59,c:'hh',t:'Học sơ cứu: xử lý hóc dị vật và CPR',n:'Kỹ năng mong không bao giờ phải dùng, nhưng có ngày nó cứu được một người.',s:'Xem video hướng dẫn từ một nguồn y tế uy tín về thủ thuật Heimlich và hồi sức tim phổi, tập động tác với chiếc gối.',p:45,k:0,ai:'abg',o:'i',g:'sct',m:'c',d:4},
{id:60,c:'hh',t:'Viết lại 5 điều học được từ cuốn sách hoặc bộ phim gần nhất',n:'Đọc mà không đọng lại thì như rót nước vào giỏ. Viết ra để giữ lại.',s:'Mở ghi chú, viết 5 gạch đầu dòng, mỗi dòng một bài học, và một việc bạn sẽ làm khác đi.',p:20,k:0,ai:'a',o:'i',g:'sctk',m:'c',d:2},
{id:61,c:'hh',t:'Luyện gõ 10 ngón 20 phút',n:'Gõ nhanh hơn một chút, mỗi ngày bạn có thêm thời gian cho việc khác.',s:'Mở một trang luyện gõ phím miễn phí, đặt hai tay đúng hàng phím cơ sở và luyện 20 phút không nhìn bàn phím.',p:20,k:0,ai:'a',o:'i',g:'sctk',m:'cx',d:3},
{id:62,c:'hh',t:'Tự làm một trang web đơn giản bằng HTML',n:'Ai cũng có thể làm ra trang web đầu tiên chỉ trong một buổi tối.',s:'Tạo file index.html, gõ một dòng tiêu đề và chèn một bức ảnh bạn thích, mở bằng trình duyệt để xem thành quả.',p:60,k:0,ai:'a',o:'i',g:'ctk',m:'ch',d:5},
// —— Kết nối
{id:63,c:'kn',t:'Gọi cho bố mẹ hoặc ông bà 10 phút',n:'Bố mẹ không cần quà to. Một cuộc gọi chẳng vì việc gì đủ làm họ vui cả tuần.',s:'Bấm gọi ngay. Mở đầu bằng: “Con gọi chẳng có việc gì, chỉ muốn hỏi hôm nay nhà mình ăn gì.”',p:10,k:0,ai:'a',o:'b',g:'sct',m:'bcl',d:1,ch:1,x:'vulan'},
{id:64,c:'kn',t:'Nhắn cho một người bạn lâu rồi không nói chuyện',n:'Có khi họ cũng đang nhớ bạn, chỉ là chưa ai nhắn trước.',s:'Lướt danh bạ tìm một người bạn cũ và gửi: “Tự nhiên nhớ hồi… Dạo này cậu thế nào rồi?”',p:10,k:0,ai:'a',o:'b',g:'sctk',m:'bl',d:2,ch:1},
{id:65,c:'kn',t:'Viết thiệp cảm ơn một người đã giúp bạn',n:'Một lời cảm ơn viết tay làm ấm lòng cả người viết lẫn người nhận.',s:'Viết 3 câu cảm ơn về một việc cụ thể người ấy đã làm gần đây, rồi hẹn một buổi cà phê để trao tận tay.',p:30,k:0,ai:'a',o:'i',g:'sct',m:'bl',d:4},
{id:66,c:'kn',t:'Rủ bạn chơi board game',n:'Màn hình nào cũng không vui bằng tiếng cười to quanh một cái bàn.',s:'Nhắn 3 người bạn, ai có bộ board game thì mang theo, hẹn ở nhà một người hoặc quán board game.',p:150,k:1,ai:'byg',o:'b',g:'ct',m:'cl',d:3},
{id:67,c:'kn',t:'Hẹn hò kiểu mới: cùng nấu một món chưa từng nấu',n:'Cháy cũng được, mặn cũng được. Đáng nhớ là lúc hai người cùng loay hoay.',s:'Hai người chọn một món trên mạng, chia nhau đi chợ, mỗi người phụ trách một nửa công thức.',p:120,k:2,ai:'y',o:'i',g:'ct',m:'cl',d:4},
{id:68,c:'kn',t:'Hỏi nhau 5 câu hỏi để thân hơn',n:'Có những điều về người thân thiết nhất mà bạn chưa từng hỏi.',s:'Cất điện thoại đi rồi lần lượt hỏi nhau: Một ngày hoàn hảo của bạn trông thế nào? Món ăn tuổi thơ bạn nhớ nhất là gì? Năm nay bạn muốn học thêm điều gì? Kỷ niệm buồn cười nhất của hai đứa là gì? Gần đây điều gì làm bạn vui?',p:60,k:0,ai:'yb',o:'b',g:'tk',m:'cl',d:4},
{id:69,c:'kn',t:'Thăm ông bà hoặc họ hàng lâu chưa ghé',n:'Ông bà luôn mong con cháu ghé chơi. Một buổi chiều ngồi nghe chuyện cũ là món quà quý.',s:'Gọi báo trước, mua ít hoa quả, ngồi lại ít nhất một tiếng và hỏi ông bà về thời trẻ của họ.',p:120,k:1,ai:'ag',o:'o',g:'sc',m:'bl',d:3,x:'cuoituan vulan'},
{id:70,c:'kn',t:'Mời một đồng nghiệp chưa thân đi cà phê',n:'Người bạn thân nào cũng từng là người lạ ngồi bàn bên cạnh.',s:'Nhắn: “Chiều nay đi cà phê 30 phút không? Mình mời.” Rồi hỏi về họ nhiều hơn nói về mình.',p:45,k:1,ai:'b',o:'o',g:'sc',m:'lc',d:5},
{id:71,c:'kn',t:'Gọi video cho nhóm bạn thân cũ',n:'Mỗi đứa một phương, nhưng một cuộc gọi là kéo cả thanh xuân về.',s:'Tạo cuộc gọi nhóm, hẹn một giờ cụ thể tối nay, mỗi người kể một chuyện dở khóc dở cười gần đây.',p:60,k:0,ai:'b',o:'i',g:'tk',m:'bl',d:3},
{id:72,c:'kn',t:'Chơi với con hoặc em nhỏ một tiếng, không điện thoại',n:'Trẻ con không nhớ món đồ chơi đắt tiền. Chúng nhớ lúc bạn bò ra sàn chơi cùng.',s:'Cất điện thoại vào ngăn kéo, để bé chọn trò và chơi đúng luật của bé.',p:60,k:0,ai:'g',o:'b',g:'sct',m:'bcxl',d:3},
{id:73,c:'kn',t:'Đọc truyện cho con trước giờ ngủ',n:'Mười lăm phút mỗi tối đủ thành một ký ức dịu dàng suốt đời.',s:'Để bé chọn một cuốn, đọc thật chậm, đổi giọng từng nhân vật rồi hỏi bé thích đoạn nào nhất.',p:20,k:0,ai:'g',o:'i',g:'tk',m:'bxl',d:1},
{id:74,c:'kn',t:'Hỏi bố mẹ về chuyện hồi họ mới quen nhau',n:'Bạn biết họ là bố mẹ, nhưng đã bao giờ biết họ thời đôi mươi chưa?',s:'Trong bữa cơm, hỏi: “Hồi xưa bố mẹ quen nhau thế nào?” Rồi chỉ việc ngồi nghe.',p:30,k:0,ai:'g',o:'i',g:'ct',m:'bl',d:3,x:'vulan'},
{id:75,c:'kn',t:'Khen thật lòng 3 người hôm nay',n:'Một lời khen đúng chỗ có thể làm sáng cả ngày của ai đó, và của bạn.',s:'Nghĩ ra 3 người, viết cho mỗi người một lời khen cụ thể chứ đừng chỉ “giỏi quá”, rồi gửi đi.',p:15,k:0,ai:'a',o:'b',g:'sct',m:'bcl',d:2,ch:1},
{id:76,c:'kn',t:'Tham gia một câu lạc bộ theo sở thích',n:'Người cùng sở thích là kiểu bạn dễ có nhất khi đã đi làm.',s:'Tìm câu lạc bộ qua trường, nơi làm, nhà văn hóa hoặc một nhóm có người quản lý rõ ràng. Buổi đầu chọn buổi gặp ở nơi công cộng, rủ một người quen đi cùng và không gửi địa chỉ hay thông tin riêng cho người lạ.',p:30,k:0,ai:'a',o:'b',g:'sctk',m:'lc',d:6},
{id:77,c:'kn',t:'Mời bạn bè đến nhà ăn lẩu',n:'Lẩu là món của sự đông vui. Càng nhiều người càng ngon.',s:'Chốt danh sách trong nhóm chat, chia nhau mua thịt, rau, nấm. Ai đến sớm thì nhặt rau.',p:180,k:2,ai:'byg',o:'i',g:'t',m:'cbl',d:4,x:'thu dong'},
{id:78,c:'kn',t:'Học nấu một món mẹ hay nấu',n:'Có những hương vị chỉ mẹ làm được. Học lại từ mẹ để món ấy theo bạn đi khắp nơi.',s:'Gọi cho mẹ: “Mẹ ơi, món… nhà mình nấu thế nào?” Ghi lại từng bước và nấu thử tối nay.',p:90,k:1,ai:'ag',o:'i',g:'sct',m:'bl',d:4,x:'vulan'},
{id:79,c:'kn',t:'Nhắn hỏi thăm một người bạn đang khó khăn',n:'Đôi khi người ta không cần lời khuyên, chỉ cần biết có người để ý.',s:'Nhắn: “Mình biết dạo này cậu nhiều chuyện. Không cần trả lời đâu, chỉ muốn nói là mình ở đây.” Nếu thấy bạn ấy gặp chuyện quá sức hoặc không an toàn, hãy báo ngay cho người lớn bạn tin hoặc gọi 115.',p:10,k:0,ai:'a',o:'b',g:'sctk',m:'bl',d:2},
{id:80,c:'kn',t:'Một buổi tối không điện thoại cùng người thương',n:'Người ngồi trước mặt quan trọng hơn mọi thông báo.',s:'Hai người cùng úp điện thoại vào một cái hộp từ 20 giờ, rồi đi dạo, nấu chè hoặc chỉ ngồi nói chuyện.',p:120,k:0,ai:'yg',o:'b',g:'t',m:'bxl',d:5},
{id:81,c:'kn',t:'Gửi một lời cảm ơn tới thầy cô cũ',n:'Người lái đò năm ấy vẫn nhớ từng chuyến. Một tin nhắn thôi cũng đủ làm thầy cô vui cả ngày.',s:'Nhắn hoặc gọi cho một thầy, cô từng ảnh hưởng tới bạn, kể bạn bây giờ đang làm gì.',p:20,k:0,ai:'a',o:'b',g:'sct',m:'bl',d:3,x:'2011'},
// —— Chăm mình
{id:82,c:'cm',t:'Ngủ trưa 20 phút',n:'Không phải lười. Nghỉ 20 phút giúp đầu óc tỉnh táo cả buổi chiều.',s:'Đặt báo thức 20 phút, tắt chuông điện thoại, che mắt và nằm xuống. Không ngủ được thì cứ nhắm mắt.',p:20,k:0,ai:'a',o:'i',g:'c',m:'mx',d:1},
{id:83,c:'cm',t:'Đi ngủ trước 23 giờ tối nay',n:'Ngày mai tốt hay không, phần lớn được quyết định từ giờ đi ngủ tối nay.',s:'Đặt báo thức 22:30 để nhắc đi ngủ, sạc điện thoại xa giường, đọc vài trang sách thay vì lướt.',p:30,k:0,ai:'a',o:'i',g:'t',m:'bmx',d:4},
{id:84,c:'cm',t:'Viết ra 3 điều biết ơn hôm nay',n:'Ngày nào cũng có ít nhất 3 điều tốt, chỉ là ta hay quên nhìn.',s:'Mở ghi chú hoặc sổ tay, viết 3 điều, nhỏ thôi cũng được: một ly trà ngon, một câu đùa của đồng nghiệp…',p:5,k:0,ai:'a',o:'b',g:'sctk',m:'bmxl',d:1,ch:1},
{id:85,c:'cm',t:'Tạm rời mạng xã hội 3 tiếng',n:'Thế giới vẫn quay khi bạn offline. Còn bạn thì được nghỉ.',s:'Đăng xuất các app mạng xã hội hoặc bật chế độ tập trung 3 tiếng, dùng thời gian đó làm một việc bằng tay.',p:180,k:0,ai:'a',o:'b',g:'sct',m:'bmxc',d:6},
{id:86,c:'cm',t:'Tập thở 4-7-8 trong 5 phút',n:'Khi lo lắng, hơi thở là thứ duy nhất bạn điều khiển được ngay lập tức.',s:'Hít vào bằng mũi 4 giây, nín thở 7 giây, thở ra bằng miệng 8 giây. Lặp lại 4 lần.',p:5,k:0,ai:'a',o:'b',g:'sctk',m:'bmx',d:1,ch:1},
{id:87,c:'cm',t:'Tắm nước ấm rồi nghe một bài nhạc nhẹ',n:'Nước ấm giúp vai gáy thả lỏng, tắm xong lên giường là dễ ngủ.',s:'Tắm nước ấm vừa phải khoảng 10 phút, để điện thoại ngoài phòng tắm. Tắm xong lau khô, uống một cốc nước rồi nằm nghe một bài nhạc nhẹ.',p:30,k:0,ai:'a',o:'i',g:'tk',m:'bmx',d:1},
{id:88,c:'cm',t:'Dọn sạch một góc nhà trong 15 phút',n:'Không gian gọn thì đầu óc cũng gọn theo. 15 phút thôi.',s:'Hẹn giờ 15 phút, chọn chỗ bừa nhất như bàn làm việc hay tủ giày, cất hoặc bỏ mọi thứ không thuộc về đó.',p:15,k:0,ai:'ag',o:'i',g:'sct',m:'cbmx',d:2,ch:1},
{id:89,c:'cm',t:'Viết nhật ký trút hết bực bội',n:'Có những điều chưa tiện nói ra, viết ra giấy trước cho nhẹ lòng. Nếu thấy nặng quá, hãy kể với một người bạn tin.',s:'Hẹn giờ 10 phút, viết liền một mạch mọi điều làm bạn khó chịu, không sửa, không đọc lại.',p:15,k:0,ai:'a',o:'i',g:'sctk',m:'bx',d:2},
{id:90,c:'cm',t:'Đi gội đầu dưỡng sinh',n:'Bạn đã làm việc chăm chỉ. Cơ thể xứng đáng được chăm lại một chút.',s:'Tìm tiệm gội đầu dưỡng sinh có nhiều đánh giá tốt gần nhà và gọi đặt lịch trước. Dưới 18 tuổi thì đi cùng người nhà.',p:90,k:2,ai:'ay',o:'o',g:'ct',m:'mx',d:2},
{id:91,c:'cm',t:'Dọn điện thoại: xóa ảnh thừa, gỡ app không dùng',n:'Điện thoại nhẹ hơn thì đầu óc cũng bớt ồn hơn.',s:'Vào phần dung lượng, gỡ 5 app một tháng nay không mở, rồi xóa ảnh chụp màn hình cũ.',p:20,k:0,ai:'a',o:'b',g:'sctk',m:'mcx',d:1,ch:1},
{id:92,c:'cm',t:'Đặt lịch khám sức khỏe hoặc lấy cao răng',n:'Tuổi trẻ không phải tấm khiên. Đi khám sớm là thương mình sớm.',s:'Gọi phòng khám gần nhà hỏi gói khám tổng quát hoặc lấy cao răng, chốt một lịch ngay trong tháng.',p:15,k:0,ai:'a',o:'b',g:'sc',m:'x',d:3},
{id:93,c:'cm',t:'Uống đủ 2 lít nước hôm nay',n:'Nhiều khi bạn không mệt. Bạn chỉ đang khát.',s:'Đổ đầy một chai 1 lít đặt trên bàn. Mục tiêu: hết 2 chai trước khi ngủ.',p:5,k:0,ai:'a',o:'b',g:'sct',m:'m',d:2,ch:1,x:'canngay'},
{id:94,c:'cm',t:'Thiền 10 phút theo video hướng dẫn',n:'Không cần làm đầu óc trống rỗng. Chỉ cần nhìn nó mà không phán xét.',s:'Ngồi thoải mái, tìm video “thiền 10 phút cho người mới”, đeo tai nghe và nhắm mắt.',p:10,k:0,ai:'a',o:'i',g:'sctk',m:'bmx',d:2,ch:1},
{id:95,c:'cm',t:'Uống một ấm trà và không làm gì cả',n:'Thỉnh thoảng không làm gì lại là việc quan trọng nhất.',s:'Pha trà, ngồi cạnh cửa sổ, không điện thoại, không sách, chỉ uống và nhìn ra ngoài 15 phút.',p:15,k:0,ai:'a',o:'i',g:'sctk',m:'bmx',d:1,x:'thu dong'},
{id:96,c:'cm',t:'Đi chân trần trên cỏ 10 phút',n:'Đất mát dưới chân nhắc bạn rằng mình đang ở đây, ngay lúc này.',s:'Tìm một bãi cỏ sạch ở công viên gần nhà, cởi giày, đi thật chậm và để ý cảm giác dưới bàn chân.',p:30,k:0,ai:'aby',o:'o',g:'sc',m:'bx',d:2},
{id:97,c:'cm',t:'Cất điện thoại xa giường và đi ngủ',n:'Khuya rồi. Việc tốt nhất bạn làm được cho ngày mai là ngủ ngay bây giờ.',s:'Sạc điện thoại ở cuối phòng hoặc phòng khác, tắt đèn, thở 4-7-8 bốn lần.',p:5,k:0,ai:'a',o:'i',g:'k',m:'bcmxlh',d:3},
{id:98,c:'cm',t:'Viết thư gửi chính mình của một năm sau',n:'Năm sau đọc lại, bạn sẽ thấy mình đã đi được một quãng xa.',s:'Viết về điều bạn đang lo, đang mong và một lời hứa với bản thân. Đặt lịch hẹn mở thư sau đúng một năm.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'bcl',d:3},
{id:99,c:'cm',t:'Nấu một nồi cháo hoặc chè ấm cho mình',n:'Tự nấu cho mình một bát ấm là cách nói: mình xứng đáng được chăm sóc.',s:'Chọn món đơn giản như cháo gà, chè đậu đen hay súp bí, xem nhà có gì và bắt tay vào nấu.',p:60,k:1,ai:'a',o:'i',g:'sct',m:'bmx',d:3,x:'thu dong'},
// —— Ăn uống
{id:100,c:'au',t:'Ăn thử một quán chưa từng ghé trong bán kính 3 km',n:'Quán ngon nhất có khi nằm ngay đầu ngõ mà bạn chưa bước vào bao giờ.',s:'Mở Google Maps, tìm quán ăn quanh chỗ bạn, chọn một quán nhiều đánh giá mà bạn chưa ăn.',p:60,k:1,ai:'abyg',o:'o',g:'sct',m:'cbl',d:2},
{id:101,c:'au',t:'Nấu một món mới từ đồ có sẵn trong tủ lạnh',n:'Bếp là phòng thí nghiệm duy nhất mà thất bại vẫn ăn được.',s:'Chụp ảnh tủ lạnh, liệt kê 4 nguyên liệu, tìm công thức hoặc hỏi AI “nấu gì từ…”.',p:60,k:0,ai:'ayg',o:'i',g:'sct',m:'cbx',d:4},
{id:102,c:'au',t:'Nấu một bữa cơm cho cả nhà',n:'Mâm cơm nóng tự tay bạn nấu là lời thương không cần nói ra.',s:'Hỏi mọi người muốn ăn gì, lên thực đơn 3 món mặn, rau, canh và đi chợ trước 17 giờ.',p:120,k:2,ai:'gy',o:'i',g:'sc',m:'bl',d:5},
{id:103,c:'au',t:'Tự pha một đồ uống mới',n:'Tự pha cho mình một ly ngon là sự tử tế nhỏ dành cho bản thân.',s:'Chọn cà phê muối, trà tắc hay matcha latte, xem nhà có gì, pha thử và tự chấm điểm từ 1 đến 10.',p:20,k:1,ai:'ay',o:'i',g:'sc',m:'cbm',d:2},
{id:104,c:'au',t:'Ăn sáng ở quán lúc 6 rưỡi',n:'Bát phở nóng lúc trời còn se lạnh. Hạnh phúc đơn giản thế thôi.',s:'Chọn quán phở, bún hay xôi đông khách nhất gần nhà, ngồi ăn thong thả, không vội.',p:45,k:1,ai:'abyg',o:'o',g:'s',m:'bl',d:3},
{id:105,c:'au',t:'Lần đầu làm bánh: bánh chuối hoặc bánh flan',n:'Mùi bánh nướng lan khắp nhà là mùi của những ngày bình yên.',s:'Chọn công thức ít nguyên liệu, xem nhà có lò nướng hoặc nồi chiên không dầu, rồi đi mua đồ.',p:120,k:1,ai:'ayg',o:'i',g:'sc',m:'cbl',d:5},
{id:106,c:'au',t:'Đi một tour ăn vặt quanh khu phố',n:'Mỗi món một ít, mỗi nơi một chút. Tour ẩm thực không cần đi xa.',s:'Rủ một người, đặt ngân sách 100 nghìn, mỗi quán chỉ thử một món và chấm điểm cho vui.',p:90,k:1,ai:'by',o:'o',g:'ct',m:'cbl',d:2},
{id:107,c:'au',t:'Ăn một món đúng mùa',n:'Mỗi mùa chỉ có vài tuần. Đừng để nó trôi qua mà chưa nếm thử.',s:'Ra chợ hỏi người bán: “Dạo này có gì đúng mùa ngon?” và mua thử một món về ăn cùng người thân.',p:20,k:1,ai:'abyg',o:'o',g:'sc',m:'bc',d:1},
{id:108,c:'au',t:'Thử ăn chay một ngày',n:'Không phải ăn kiêng. Chỉ là cho cơ thể nghỉ ngơi và thử một cách ăn khác.',s:'Lên 3 bữa chay đơn giản như rau luộc, đậu phụ, canh nấm, hoặc tìm một quán chay gần nhà cho bữa trưa.',p:30,k:1,ai:'abyg',o:'b',g:'sc',m:'cx',d:4,x:'ram canngay'},
{id:109,c:'au',t:'Chuẩn bị cơm hộp đi làm cả tuần',n:'Một buổi chuẩn bị, năm ngày ăn ngon mà lại tiết kiệm.',s:'Lên thực đơn 5 bữa trưa, đi chợ một lần, nấu 2 món mặn, chia hộp và cất ngăn mát.',p:150,k:2,ai:'ay',o:'i',g:'sc',m:'ch',d:6,x:'cuoituan'},
{id:110,c:'au',t:'Picnic mini ngay tại nhà',n:'Không cần đi xa. Một tấm khăn và vài món ngon là thành chuyến đi.',s:'Trải chiếu ở phòng khách, sân nhà hoặc một góc công viên gần nhà, bày vài món ăn nhẹ, mở nhạc và rủ người nhà ngồi cùng.',p:60,k:1,ai:'ayg',o:'b',g:'ct',m:'cbl',d:2},
{id:111,c:'au',t:'Học gói một món: nem, bánh cuốn hay sủi cảo',n:'Ngồi quây quần gói đồ ăn là cách trò chuyện tự nhiên nhất.',s:'Chọn một món, xem video hướng dẫn, mua nguyên liệu và rủ cả nhà cùng gói.',p:120,k:2,ai:'gyb',o:'i',g:'sct',m:'cbl',d:5},
// —— Sự nghiệp & tiền
{id:112,c:'sn',t:'Cập nhật CV và hồ sơ LinkedIn',n:'Cơ hội thường đến lúc bạn chưa chuẩn bị. Hôm nay chuẩn bị sẵn.',s:'Mở CV cũ, thêm 3 việc bạn làm tốt nhất năm qua kèm con số cụ thể, thay ảnh đại diện mới.',p:60,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:4},
{id:113,c:'sn',t:'Ghi lại mọi khoản chi tiêu hôm nay',n:'Tiền không tự nhiên biến mất. Ghi ra là biết nó đi đâu.',s:'Mỗi lần tiêu gì, ghi ngay vào điện thoại số tiền và món gì. Tối cộng lại xem có bất ngờ không.',p:10,k:0,ai:'a',o:'b',g:'sct',m:'cx',d:2,ch:1,x:'canngay'},
{id:114,c:'sn',t:'Lập ngân sách tháng tới theo quy tắc 50/30/20',n:'Thu nhập bao nhiêu không quan trọng bằng bạn giữ lại được bao nhiêu.',s:'Chia thu nhập: 50% cho thiết yếu, 30% cho mong muốn, 20% để dành. Lập một bảng 3 cột ngay trên điện thoại.',p:45,k:0,ai:'ay',o:'i',g:'sctk',m:'cx',d:4},
{id:115,c:'sn',t:'Tìm hiểu một việc làm thêm: viết, thiết kế, dịch',n:'Một kỹ năng thứ hai là chiếc phao khi công việc chính chòng chành.',s:'Chọn một kỹ năng bạn đã có nền tảng, đọc 3 tin tuyển cộng tác viên để biết người ta đang cần gì.',p:60,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:5},
{id:116,c:'sn',t:'Bán một món đồ không còn dùng',n:'Đồ nằm góc nhà thành tiền, nhà rộng thêm. Một công đôi việc.',s:'Chụp 3 ảnh rõ nét, viết mô tả trung thực và đăng lên một nhóm hoặc ứng dụng mua bán đồ cũ. Hẹn giao ở nơi công cộng hoặc gửi qua bưu cục, không cho người lạ địa chỉ nhà; dưới 18 tuổi thì nhờ người nhà cùng làm.',p:30,k:0,ai:'a',o:'b',g:'sctk',m:'cx',d:3},
{id:117,c:'sn',t:'Viết ra công việc mơ ước và 3 bước để tới gần',n:'Ước mơ chưa có bước đi thì vẫn chỉ là mơ. Có bước đi rồi thì thành kế hoạch.',s:'Viết công việc bạn muốn làm sau 5 năm, 3 kỹ năng còn thiếu và một việc nhỏ làm trong tuần này.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'cbh',d:4},
{id:118,c:'sn',t:'Nhắn hỏi một người đi trước trong nghề',n:'Hầu hết người giỏi đều sẵn lòng chỉ đường, nếu bạn hỏi tử tế.',s:'Chọn một người làm nghề bạn mơ ước và nhắn: “Em rất ngưỡng mộ công việc của anh/chị. Em xin hỏi 2 câu trong 10 phút được không ạ?”',p:20,k:0,ai:'a',o:'b',g:'sc',m:'ch',d:7},
{id:119,c:'sn',t:'Đọc về lãi kép và quỹ dự phòng',n:'Hiểu lãi kép sớm 5 năm có thể tạo ra khác biệt rất lớn về sau.',s:'Đọc một bài cơ bản về lãi kép và quỹ dự phòng, rồi tự tính: mỗi tháng để dành một khoản thì sau 5 năm được bao nhiêu.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'c',d:3},
{id:120,c:'sn',t:'Dành 1 tiếng cho dự án cá nhân bạn cứ hẹn mãi',n:'Dự án dang dở không tự xong. Nhưng một tiếng mỗi ngày thì có.',s:'Mở dự án ra, chọn đúng một việc nhỏ nhất làm xong được trong một tiếng, bật hẹn giờ và bắt đầu.',p:60,k:0,ai:'a',o:'i',g:'sctk',m:'chx',d:5},
{id:121,c:'sn',t:'Dọn hộp thư email',n:'Hộp thư gọn, đầu óc nhẹ. Bước vào tuần mới không còn nợ cũ.',s:'Lưu trữ mọi email cũ hơn một tháng, hủy đăng ký 5 bản tin không đọc, trả lời những email mất dưới 2 phút.',p:45,k:0,ai:'a',o:'i',g:'sc',m:'cx',d:3},
{id:122,c:'sn',t:'Tập giới thiệu bản thân trong 2 phút',n:'Người nói tự tin không sinh ra đã giỏi. Họ chỉ tập nhiều hơn một chút.',s:'Bật camera trước, giới thiệu bản thân trong 2 phút, xem lại, sửa một điều rồi quay lần hai.',p:20,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:5},
{id:123,c:'sn',t:'Mở một tài khoản tiết kiệm cho một mục tiêu',n:'Tiết kiệm bằng ý chí thì khó. Tiết kiệm bằng thói quen tự động thì dễ.',s:'Chọn một mục tiêu như quỹ dự phòng hay một chuyến đi, mở tài khoản tiết kiệm riêng trên app ngân hàng của bạn.',p:20,k:0,ai:'a',o:'b',g:'sctk',m:'cx',d:4},
{id:124,c:'sn',t:'Viết 3 mục tiêu cho 90 ngày tới',n:'Không cần lo cho cả đời. 90 ngày rõ ràng đã đủ đưa bạn đi xa.',s:'Viết 3 mục tiêu cho sức khỏe, công việc và bản thân, mỗi mục tiêu kèm một việc làm ngay trong tuần.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:4},
// —— Sống tử tế
{id:125,c:'tt',t:'Nhặt rác 20 phút quanh nơi bạn sống',n:'Thế giới không sạch lên vì một người. Nhưng con ngõ nhà bạn thì có.',s:'Mang găng tay và một túi to, đi một vòng ngõ hoặc công viên gần nhà, nhặt đến khi đầy túi.',p:30,k:0,ai:'abyg',o:'o',g:'sc',m:'cbx',d:4},
{id:126,c:'tt',t:'Đi hiến máu nhân đạo',n:'Một lần hiến máu có thể góp phần cứu một người.',s:'Nếu bạn từ đủ 18 tuổi, tìm điểm hiến máu cố định hoặc lịch hiến máu lưu động gần bạn, xem điều kiện sức khỏe và ăn nhẹ trước khi đi.',p:90,k:0,ai:'ab',o:'o',g:'sc',m:'ch',d:7},
{id:127,c:'tt',t:'Dạy ai đó một điều bạn giỏi',n:'Cho đi kiến thức không làm bạn mất gì, chỉ làm nó sâu thêm.',s:'Nghĩ một việc bạn làm tốt như Excel, nấu ăn hay chơi đàn, rồi đề nghị dạy em, bạn hoặc đồng nghiệp 30 phút.',p:45,k:0,ai:'abg',o:'b',g:'sct',m:'bcl',d:4},
{id:128,c:'tt',t:'Mời một bữa ăn cho người lao động vất vả',n:'Một hộp cơm, một chai nước. Với họ là bữa trưa, với bạn là một ngày ý nghĩa.',s:'Khi mua đồ ăn, mua thêm một suất và gửi bác xe ôm, cô lao công hoặc người bán hàng rong gần đó.',p:20,k:1,ai:'ab',o:'o',g:'sc',m:'bc',d:3},
{id:129,c:'tt',t:'Viết đánh giá tốt cho một quán nhỏ bạn quý',n:'Một đánh giá thật lòng có giá trị với quán nhỏ hơn bạn tưởng.',s:'Nghĩ tới quán bạn hay ghé, vào Google Maps viết 3 câu thật lòng và kèm một bức ảnh.',p:10,k:0,ai:'a',o:'b',g:'sctk',m:'c',d:1,ch:1},
{id:130,c:'tt',t:'Dạy ông bà dùng điện thoại gọi video',n:'Ông bà từng dạy bạn cầm thìa. Giờ đến lượt bạn dạy ông bà gọi video.',s:'Ngồi cạnh ông bà, chỉ đúng một việc là gọi video cho con cháu, và để ông bà tự bấm.',p:45,k:0,ai:'g',o:'i',g:'sct',m:'bl',d:3},
{id:131,c:'tt',t:'Quyên góp sách cũ',n:'Cuốn sách bạn đọc xong có thể mở ra cả một thế giới cho một đứa trẻ khác.',s:'Chọn 5 cuốn còn tốt, tìm một nhóm hoặc dự án nhận sách cho vùng khó khăn và liên hệ gửi.',p:45,k:0,ai:'ag',o:'b',g:'sctk',m:'c',d:3},
{id:132,c:'tt',t:'Tình nguyện một buổi ở mái ấm hoặc viện dưỡng lão',n:'Tưởng mình đi giúp người, hóa ra người ta giúp mình hiểu điều gì quan trọng.',s:'Gọi trước cho một cơ sở gần nhà hỏi họ đang cần gì, công sức hay đồ dùng, rồi đăng ký một buổi.',p:240,k:1,ai:'abg',o:'o',g:'sc',m:'c',d:7,x:'cuoituan'},
{id:133,c:'tt',t:'Cảm ơn một người ít khi được cảm ơn',n:'Họ làm cuộc sống của bạn trơn tru mỗi ngày. Một câu cảm ơn đáng giá hơn bạn nghĩ.',s:'Hôm nay gặp bác bảo vệ, cô lao công hay anh giao hàng, hãy nhìn vào mắt họ và nói: “Cảm ơn nhiều nhé.”',p:5,k:0,ai:'a',o:'o',g:'sct',m:'bc',d:1,ch:1},
{id:134,c:'tt',t:'Gom quần áo cũ để quyên góp',n:'Chiếc áo bạn không còn mặc có thể là chiếc áo ấm của ai đó mùa đông này.',s:'Lấy hết quần áo ra, cái nào cả năm không mặc thì gấp vào thùng, tìm điểm nhận quyên góp gần nhà.',p:90,k:0,ai:'ag',o:'i',g:'sct',m:'cx',d:4,x:'thu dong'},
{id:135,c:'tt',t:'Giúp một việc nhỏ mà không ai nhờ',n:'Tử tế không cần ai chứng kiến. Bạn biết là đủ.',s:'Hôm nay làm một việc không ai giao: rửa bát hộ, dọn bàn chung, đổ rác giúp hàng xóm.',p:10,k:0,ai:'abyg',o:'b',g:'sct',m:'bcl',d:1,ch:1},
// —— Giải trí
{id:136,c:'gt',t:'Xem một bộ phim kinh điển bạn chưa từng xem',n:'Có những bộ phim người ta nhắc mãi là có lý do. Hôm nay tự tìm hiểu xem.',s:'Tìm danh sách phim kinh điển được đánh giá cao, chọn một phim chưa xem trên nền tảng có bản quyền.',p:120,k:0,ai:'ayg',o:'i',g:'ctk',m:'cbmx',d:1},
{id:137,c:'gt',t:'Đi hát karaoke xả stress',n:'Hát dở không sao. Hát to mới đúng tinh thần.',s:'Rủ 3–5 người, đặt phòng trước, mỗi người chuẩn bị một bài tủ và một bài chưa hát bao giờ.',p:120,k:2,ai:'byg',o:'o',g:'t',m:'bxl',d:3},
{id:138,c:'gt',t:'Đi xem phim ở rạp',n:'Màn hình lớn, điện thoại tắt, hai tiếng sống trong một thế giới khác.',s:'Mở trang của rạp gần nhất, chọn một phim đang chiếu có đánh giá tốt và đặt vé suất tối nay.',p:150,k:2,ai:'abyg',o:'o',g:'ct',m:'cbml',d:2},
{id:139,c:'gt',t:'Chơi một game hai người cùng bạn',n:'Hợp sức qua màn khó là một kiểu tình bạn rất riêng.',s:'Chọn một game co-op trên điện thoại hoặc máy tính và rủ bạn vào chơi cùng một tiếng.',p:60,k:0,ai:'by',o:'i',g:'ctk',m:'cl',d:2},
{id:140,c:'gt',t:'Ghép một bộ puzzle hoặc lego',n:'Từng mảnh nhỏ khớp vào nhau, cảm giác bình yên khó tả.',s:'Lấy bộ có sẵn hoặc mua một bộ nhỏ, trải ra bàn, bật nhạc nhẹ và bắt đầu từ các mảnh viền.',p:90,k:1,ai:'ayg',o:'i',g:'ctk',m:'bmx',d:3},
{id:141,c:'gt',t:'Chơi bowling hoặc bi-a với bạn',n:'Thắng hay thua thì cũng cười to là được.',s:'Rủ 2–3 người, chọn khu bowling hoặc bi-a trong trung tâm thương mại, nhà văn hóa và đặt luật vui: ai thua phải kể một chuyện xấu hổ.',p:120,k:2,ai:'by',o:'o',g:'ct',m:'cl',d:2},
{id:142,c:'gt',t:'Học một điệu nhảy đang hot',n:'Nhảy chưa đều cũng vui. Quay lại để 5 năm sau còn cười.',s:'Chọn một điệu ngắn, xem ở tốc độ 0,5x, tập từng 8 nhịp và quay video ở lần thứ năm.',p:30,k:0,ai:'aby',o:'i',g:'sct',m:'ch',d:4},
{id:143,c:'gt',t:'Đấu một ván cờ vua hoặc cờ tướng',n:'Ván cờ hay là ván cả hai người đều phải nghĩ.',s:'Rủ người thân chơi một ván, hoặc mở một app cờ để đấu với người lạ cùng trình độ.',p:45,k:0,ai:'abg',o:'b',g:'sctk',m:'cmx',d:3},
{id:144,c:'gt',t:'Xem lại ảnh vui của 5 năm trước',n:'Có những khoảnh khắc vui đáng được gửi lại cho người cùng trải qua.',s:'Mở thư viện ảnh, lọc theo năm, chọn 3 tấm làm bạn bật cười và gửi cho người trong ảnh kèm câu: “Nhớ hồi này không?”',p:20,k:0,ai:'a',o:'b',g:'sctk',m:'bl',d:1,ch:1},
{id:145,c:'gt',t:'Tổ chức một buổi chiếu phim tại nhà',n:'Chăn, bỏng ngô và những người bạn thương. Rạp chiếu phim tốt nhất là đây.',s:'Chọn phim, chuẩn bị bỏng ngô và đồ uống, tắt đèn, mời 2–3 người đến lúc 20 giờ.',p:180,k:1,ai:'byg',o:'i',g:'t',m:'cbl',d:3},
{id:146,c:'gt',t:'Chơi đố vui với cả nhóm',n:'Thua thì biết thêm một điều. Thắng thì được khoe.',s:'Mỗi người soạn 5 câu hỏi về một chủ đề mình thích, rồi thay phiên đố nhau.',p:45,k:0,ai:'byg',o:'b',g:'ctk',m:'cl',d:2},
{id:147,c:'gt',t:'Đi xem một trận đấu hoặc buổi diễn trực tiếp',n:'Hàng nghìn người cùng hò reo một lúc. Cảm giác ấy không màn hình nào có.',s:'Tìm lịch thi đấu hoặc lịch diễn sắp tới gần bạn, chọn một sự kiện và mua vé ở kênh chính thức.',p:180,k:3,ai:'by',o:'o',g:'t',m:'ch',d:5},
{id:148,c:'gt',t:'Nằm nghe trọn một album nhạc',n:'Nghệ sĩ xếp từng bài theo thứ tự có lý do. Nghe trọn một lần xem sao.',s:'Chọn một album chứ không phải playlist, nằm xuống, đeo tai nghe và nghe từ bài đầu đến bài cuối.',p:45,k:0,ai:'ay',o:'i',g:'ctk',m:'bmx',d:1},
// —— Quẻ theo dịp (chỉ hiện quanh ngày đó)
{id:149,c:'st',ev:'halloween',t:'Làm bộ hóa trang Halloween từ đồ cũ',n:'Mỗi năm có một ngày được làm người khác. Đừng bỏ lỡ.',s:'Lục tủ đồ cũ, chọn một nhân vật dễ làm, tận dụng đồ có sẵn và thêm chút màu vẽ mặt.',p:90,k:1,ai:'aby',o:'i',g:'sct',m:'ch',d:4},
{id:150,c:'au',ev:'halloween',t:'Khắc một quả bí ngô cười',n:'Quả bí khắc mặt cười đặt ở cửa, cả xóm đi qua cũng vui lây.',s:'Mua một quả bí nhỏ, vẽ khuôn mặt bằng bút, khoét từ đỉnh và đặt một ngọn nến điện bên trong.',p:90,k:1,ai:'ayg',o:'i',g:'sct',m:'cb',d:4},
{id:151,c:'kn',ev:'2011',t:'Về thăm thầy cô cũ dịp 20/11',n:'Thầy cô nhớ học trò lâu hơn học trò nhớ thầy cô. Về thăm một lần đi.',s:'Rủ vài bạn cũ, gọi hỏi thầy cô có ở nhà không, mua một bó hoa nhỏ rồi ghé thăm.',p:120,k:1,ai:'ab',o:'o',g:'sct',m:'bl',d:5},
{id:152,c:'st',ev:'noel',t:'Tự làm thiệp Giáng sinh tặng 3 người',n:'Một tấm thiệp viết tay giữa mùa lễ ấm hơn mọi tin nhắn.',s:'Mua giấy bìa màu, gấp đôi, vẽ một cây thông nhỏ và viết cho mỗi người một lời chúc riêng.',p:60,k:1,ai:'abyg',o:'i',g:'sctk',m:'cbl',d:3},
{id:153,c:'kp',ev:'noel',t:'Đi ngắm phố trang trí Giáng sinh',n:'Đèn lấp lánh khắp phố, ai đi qua cũng thấy lòng ấm lên.',s:'Chọn nhà thờ hoặc tuyến phố trang trí gần nhất, đi trước 19 giờ cho đỡ đông.',p:150,k:1,ai:'abyg',o:'o',g:'t',m:'cbl',d:3},
{id:154,c:'kn',ev:'tet',t:'Dọn nhà đón Tết cùng gia đình',n:'Dọn nhà cuối năm là dọn cả những điều cũ trong lòng.',s:'Chia việc cho từng người, bật nhạc xuân, bắt đầu từ bàn thờ và phòng khách.',p:180,k:0,ai:'g',o:'i',g:'sc',m:'cbl',d:5},
{id:155,c:'au',ev:'tet',t:'Cùng gia đình gói bánh chưng',n:'Ngồi canh nồi bánh chưng là đêm dài nhất và ấm nhất trong năm.',s:'Hỏi ông bà, bố mẹ cách gói, chuẩn bị lá dong, gạo nếp, đỗ, thịt và xếp lịch luộc bánh.',p:480,k:2,ai:'g',o:'b',g:'sct',m:'ch',d:7},
{id:156,c:'st',ev:'trungthu',t:'Tự làm một chiếc đèn ông sao',n:'Ánh đèn tự tay làm luôn sáng hơn đèn mua ngoài chợ.',s:'Chuẩn bị nan tre, giấy bóng kính, dây thép nhỏ và một bóng đèn LED nhỏ thay cho nến. Xem video hướng dẫn và làm cùng em nhỏ trong nhà.',p:120,k:1,ai:'ag',o:'i',g:'sct',m:'cbl',d:5},
{id:157,c:'kn',ev:'phunu',t:'Nấu một bữa và tặng hoa cho mẹ, chị em gái',n:'Người phụ nữ trong nhà quen chăm sóc người khác. Hôm nay đổi vai một lần.',s:'Mua một bó hoa nhỏ, nấu món mẹ thích và viết một tấm thiệp ngắn đặt cạnh mâm cơm.',p:120,k:2,ai:'g',o:'i',g:'sct',m:'bl',d:4},
{id:158,c:'kn',ev:'valentine',t:'Hẹn hò đúng nghĩa, không cần đắt tiền',n:'Món quà quý nhất ngày lễ tình nhân là thời gian trọn vẹn cho nhau.',s:'Lên kế hoạch 3 chặng: một món ăn, một nơi dạo bộ, một câu hỏi bạn chưa từng hỏi người ấy.',p:180,k:2,ai:'y',o:'o',g:'ct',m:'cl',d:4},
{id:159,c:'cm',ev:'valentine',t:'Hẹn hò với chính mình',n:'Độc thân không có nghĩa là thiếu. Hôm nay chiều mình hết cỡ.',s:'Mua cho mình một bông hoa, ăn một món thật ngon và xem bộ phim bạn thích nhất.',p:120,k:1,ai:'a',o:'b',g:'ct',m:'bcl',d:2},
{id:160,c:'kn',ev:'giadinh',t:'Bữa cơm đủ mặt nhân Ngày Gia đình',n:'Một bữa cơm đông đủ là điều ai sống xa nhà cũng nhớ.',s:'Nhắn nhóm gia đình chốt giờ ăn tối, mỗi người góp một món và cất điện thoại khi ngồi vào mâm.',p:120,k:1,ai:'g',o:'i',g:'t',m:'bl',d:3},
{id:161,c:'kn',ev:'thieunhi',t:'Đưa em nhỏ đi chơi ngày 1/6',n:'Ngày của trẻ con, nhưng người lớn đi cùng cũng được trẻ lại.',s:'Chọn công viên hoặc khu vui chơi gần nhà, chuẩn bị nước, mũ và để bé chọn trò.',p:180,k:2,ai:'g',o:'o',g:'sc',m:'cbl',d:3},
{id:162,c:'cm',ev:'giaothua',t:'Tổng kết năm cũ bằng 10 dòng',n:'Năm nay bạn đã đi qua nhiều hơn bạn nghĩ. Viết ra để thấy.',s:'Viết 5 điều bạn tự hào trong năm, 3 điều muốn bỏ lại và 2 điều muốn mang sang năm mới.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'bch',d:2},
{id:163,c:'kp',ev:'ram',t:'Đi chùa và ăn một bữa chay',n:'Theo nếp nhà, ngày rằm, mùng Một là dịp lòng chậm lại, ăn thanh đạm và nghĩ về điều tốt.',s:'Hỏi mẹ hoặc bà xem nhà mình có làm lễ không, phụ một tay chuẩn bị rồi cùng nhau đi chùa gần nhà.',p:90,k:1,ai:'ayg',o:'b',g:'sct',m:'bxl',d:3},
{id:164,c:'gt',ev:'cathangtu',t:'Bày một trò đùa Cá tháng Tư vô hại',n:'Trò đùa hay là trò mà người bị đùa cũng bật cười.',s:'Ví dụ: dán mắt nhựa lên đồ trong tủ lạnh. Tránh trò làm người khác xấu hổ hoặc lo lắng thật.',p:15,k:0,ai:'abyg',o:'i',g:'sct',m:'ch',d:2},
{id:165,c:'tt',ev:'doan',t:'Tham gia một hoạt động tình nguyện của Đoàn',n:'Tuổi trẻ cùng nhau làm một việc có ích là tuổi trẻ đáng nhớ.',s:'Hỏi Đoàn trường, Đoàn phường hoặc nơi làm việc xem dịp 26/3 có hoạt động nào và đăng ký một buổi.',p:180,k:0,ai:'ab',o:'o',g:'sc',m:'chl',d:6},
{id:166,c:'kp',ev:'nghile',t:'Nghỉ lễ: đi một chuyến ngắn gần nhà',n:'Không cần đi xa mới gọi là đi chơi. Gần nhà cũng có những nơi đẹp bạn chưa biết.',s:'Chọn một điểm trong vòng 50 km, đi sớm để tránh đông, mang theo nước và đồ ăn nhẹ.',p:360,k:2,ai:'abyg',o:'o',g:'s',m:'cbhl',d:5},
// —— Quẻ khó (7–10 sao), làm được cả buổi tối
{id:167,c:'cm',t:'Một ngày trọn vẹn không mạng xã hội',n:'Một ngày không lướt, bạn sẽ ngạc nhiên vì mình có nhiều thời gian đến thế.',s:'Gỡ tạm các app mạng xã hội khỏi màn hình chính, báo trước với người thân và ghi lại những gì bạn làm thay vào đó.',p:15,k:0,ai:'a',o:'b',g:'sctk',m:'cmx',d:8,x:'canngay'},
{id:168,c:'st',t:'Viết và chia sẻ một bài học nhỏ của bạn',n:'Một điều bạn học được có thể giúp người khác đỡ mất công.',s:'Chọn một kinh nghiệm hay hoặc một mẹo bạn rút ra gần đây, viết 300 chữ, đăng ở chế độ bạn bè và không ghi tên trường, địa chỉ hay thông tin riêng.',p:45,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:7},
{id:169,c:'kn',t:'Chủ động làm lành với một người',n:'Một tin nhắn làm lành có thể mở lại một tình bạn đáng giữ.',s:'Nếu bạn thấy sẵn sàng và mối quan hệ này an toàn với bạn, nhắn một câu ngắn như “Dạo này mình nhớ cậu, mình nói chuyện lại nhé?”. Không cần giải quyết hết trong một lần.',p:20,k:0,ai:'a',o:'b',g:'sct',m:'ch',d:8},
{id:170,c:'kn',t:'Bắt chuyện với một người lạ 5 phút',n:'Ai cũng có một câu chuyện thú vị. Bạn chỉ cần là người hỏi trước.',s:'Ở quán cà phê, công viên hay lúc xếp hàng, mở lời bằng một câu hỏi nhỏ về điều đang diễn ra xung quanh. Chỉ trò chuyện ở nơi đông người, không cho số điện thoại, địa chỉ hay trường lớp.',p:15,k:0,ai:'a',o:'o',g:'sct',m:'ch',d:7},
{id:171,c:'vd',t:'Chạy 5 km, chậm mà chắc',n:'5 km là mốc nhiều người nghĩ mình không làm được, cho tới khi làm được.',s:'Khởi động 5 phút, mang nước, chạy chậm đến mức vẫn nói chuyện được. Mệt thì đi bộ một đoạn rồi chạy tiếp; thấy chóng mặt, tức ngực hay khó thở thì dừng hẳn và nghỉ.',p:50,k:0,ai:'ab',o:'o',g:'sct',m:'chx',d:8},
{id:172,c:'sn',t:'Làm xong việc bạn trì hoãn lâu nhất',n:'Việc nặng nhất thường chỉ mất một buổi. Thứ nặng thật là sự trì hoãn.',s:'Viết ra việc bạn ngại nhất, chia thành 3 bước nhỏ và làm bước đầu tiên ngay trong 25 phút.',p:90,k:0,ai:'a',o:'b',g:'sctk',m:'cxh',d:8},
{id:173,c:'vd',t:'Đăng ký một giải chạy hoặc giải đấu phong trào',n:'Có ngày đích rõ ràng, việc tập luyện tự nhiên có lý do.',s:'Tìm một giải trong 2–3 tháng tới, đọc kỹ điều lệ và đăng ký cự ly hoặc nội dung vừa sức.',p:30,k:3,ai:'ab',o:'i',g:'sctk',m:'ch',d:7},
{id:174,c:'cm',t:'Ngày mai dậy lúc 5 giờ sáng',n:'Một giờ yên tĩnh trước khi cả nhà thức dậy là món quà lớn cho chính mình.',s:'Đi ngủ trước 21:30 để ngủ đủ 7–8 tiếng, đặt báo thức xa giường và chuẩn bị sẵn việc đầu tiên sẽ làm khi dậy.',p:15,k:0,ai:'a',o:'i',g:'t',m:'cxh',d:7},
{id:175,c:'sn',t:'Gửi CV ứng tuyển một công việc bạn thích',n:'Không gửi thì chắc chắn không có. Gửi đi thì còn cơ hội.',s:'Tìm một tin tuyển dụng làm bạn hào hứng, chỉnh CV theo đúng yêu cầu của tin và bấm gửi trước khi đi ngủ.',p:60,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:8},
{id:176,c:'hh',t:'30 phút chỉ nói tiếng Anh',n:'Sợ nói sai là rào cản lớn nhất. Hôm nay cứ sai thoải mái.',s:'Rủ một người bạn hoặc luyện nói với AI, đặt hẹn giờ 30 phút và chỉ dùng tiếng Anh cho tới khi chuông reo.',p:30,k:0,ai:'ab',o:'i',g:'sctk',m:'ch',d:7},
{id:177,c:'kn',t:'Chốt lịch họp mặt nhóm bạn cũ',n:'Ai cũng nói “hôm nào gặp nhau đi”. Hôm nay bạn là người chốt ngày.',s:'Tạo nhóm chat, đưa ra 2 ngày và 1 địa điểm cụ thể, ai rảnh thì chốt luôn trong tối nay.',p:30,k:0,ai:'ab',o:'b',g:'sctk',m:'ch',d:7},
{id:178,c:'tt',t:'Đăng ký một dự án tình nguyện dài hạn',n:'Một buổi giúp đỡ là kỷ niệm. Một dự án dài hơi sẽ thành một phần con người bạn.',s:'Tìm các nhóm tình nguyện uy tín ở tỉnh, thành của bạn, đọc yêu cầu và gửi đăng ký cho một dự án hợp lịch.',p:45,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:7},
// —— Quẻ vui, rẻ, có bạn
{id:179,c:'gt',t:'Chụp photobooth cùng bạn thân',n:'Bốn kiểu ảnh ngố trên một dải giấy nhỏ, giữ được cả chục năm.',s:'Tìm tiệm photobooth hoặc chụp ảnh lấy liền gần nhà, rủ một người và nghĩ trước 4 kiểu tạo dáng.',p:60,k:1,ai:'by',o:'o',g:'ct',m:'cbl',d:2},
{id:180,c:'gt',t:'Xem phim suất khuya ở rạp',n:'Rạp vắng, ghế êm, cả phòng chiếu gần như của riêng bạn.',s:'Đặt vé suất sau 21 giờ ở rạp gần nhà, rủ một người đi cùng, mua một bắp rang, tắt chuông điện thoại và báo người nhà giờ về.',p:150,k:2,ai:'by',o:'o',g:'t',m:'ch',d:2},
{id:181,c:'gt',t:'Đi trượt patin hoặc chơi ở khu vui chơi',n:'Ngã vài lần rồi cười. Người lớn cũng cần được chơi.',s:'Tìm sân trượt hoặc khu vui chơi trong nhà gần nhất, rủ 2–3 người và đi vào giờ vắng.',p:120,k:2,ai:'byg',o:'o',g:'ct',m:'chl',d:3},
{id:182,c:'kp',t:'Ngồi quán cà phê có view đẹp tới hoàng hôn',n:'Một ly nước, một góc nhìn rộng, vậy là đủ một buổi chiều.',s:'Tìm quán nhìn ra công viên hoặc một con phố rộng gần bạn, chọn bàn trong nhà cạnh cửa kính, đến trước giờ mặt trời lặn 30 phút và rủ một người đi cùng.',p:120,k:1,ai:'aby',o:'o',g:'c',m:'cbxl',d:2,x:'hoanghon'},
{id:183,c:'gt',t:'Hát karaoke tại nhà bằng YouTube',n:'Không cần phòng hát, chỉ cần một cái loa và tinh thần không ngại.',s:'Mở YouTube trên TV hoặc điện thoại nối loa, gõ tên bài kèm chữ “karaoke”, mỗi người chọn một bài.',p:60,k:0,ai:'byg',o:'i',g:'ct',m:'cbl',d:1},
{id:184,c:'au',t:'Thử một món đường phố chưa ăn bao giờ',n:'Ốc, nộm bò khô, bánh tráng nướng… còn cả trăm món đang chờ bạn.',s:'Nghĩ một món bạn nghe nhiều mà chưa thử, tìm quán gần nhất trên bản đồ và đi ăn thử.',p:45,k:1,ai:'aby',o:'o',g:'ct',m:'ch',d:2},
{id:185,c:'kn',t:'Rủ bạn đi ăn tối muộn',n:'Bát phở tối muộn ngon hơn hẳn khi có người ngồi cùng.',s:'Rủ một người bạn, hẹn quán gần nhà, đi chung một xe hoặc đón nhau và về nhà trước 23 giờ.',p:60,k:1,ai:'by',o:'o',g:'t',m:'cbl',d:2},
{id:186,c:'st',t:'Chụp 10 khoảnh khắc nhỏ của ngày hôm nay',n:'Không cần đẹp, chỉ cần thật. Mười tấm ảnh kể lại một ngày.',s:'Từ giờ đến tối, chụp 10 thứ nhỏ như ly nước, vệt nắng, đôi giày, rồi ghép thành một bài đăng.',p:20,k:0,ai:'aby',o:'b',g:'sct',m:'cbh',d:2,ch:1},
{id:187,c:'kp',t:'Đi phượt một ngày bằng xe máy cùng bạn',n:'Gió, con đường và mấy đứa bạn. Kiểu chuyến đi nhớ lâu nhất.',s:'Người cầm lái phải đủ 18 tuổi và có bằng lái phù hợp; dưới 18 tuổi thì đi xe khách hoặc nhờ người lớn chở. Chọn điểm trong vòng 80 km, kiểm tra xe, đội mũ bảo hiểm, đi đúng tốc độ, xuất phát sớm và về trước khi trời tối.',p:480,k:2,ai:'by',o:'o',g:'s',m:'ch',d:7,x:'cuoituan'},
{id:188,c:'au',t:'Tự pha trà sữa trân châu tại nhà',n:'Ngọt vừa đủ, trân châu tự nấu, rẻ hơn ngoài tiệm.',s:'Chuẩn bị trà đen, sữa tươi và trân châu khô, xem một video hướng dẫn ngắn rồi pha.',p:45,k:1,ai:'aby',o:'i',g:'sct',m:'cbl',d:3},
{id:189,c:'gt',t:'Đi quán cà phê board game hoặc cà phê mèo',n:'Một chỗ để chơi, để cười và vuốt ve vài chú mèo lười.',s:'Tìm quán board game hoặc quán cà phê thú cưng gần bạn, xem giờ mở cửa và rủ một người.',p:120,k:2,ai:'aby',o:'o',g:'ct',m:'cbl',d:2},
{id:190,c:'kn',t:'Hẹn bạn đi bộ tám chuyện thay vì ngồi quán',n:'Đi bộ cạnh nhau, chuyện khó nói tự nhiên dễ nói hơn.',s:'Nhắn: “Đi bộ một vòng hồ không?”, hẹn giờ trời mát và mang theo chai nước.',p:60,k:0,ai:'by',o:'o',g:'sct',m:'bcl',d:2},
{id:191,c:'gt',t:'Xem lại một bộ phim hoạt hình tuổi thơ',n:'Lớn rồi xem lại, bạn sẽ hiểu những điều hồi bé chưa hiểu.',s:'Chọn bộ phim bạn mê hồi nhỏ trên nền tảng có bản quyền, chuẩn bị đồ ăn vặt và xem trọn.',p:90,k:0,ai:'ayg',o:'i',g:'ctk',m:'bmxl',d:1},
{id:192,c:'st',t:'Quay một video 30 giây chia sẻ mẹo bạn biết',n:'Bạn biết những điều người khác đang cần. Một mẹo nhỏ là đủ để bắt đầu.',s:'Chọn một mẹo bạn giỏi như nấu ăn, Excel hay sửa xe, quay 30 giây, thêm phụ đề rồi đăng.',p:45,k:0,ai:'a',o:'b',g:'sct',m:'ch',d:5},
{id:193,c:'kp',t:'Đi một hội chợ hoặc sự kiện cuối tuần',n:'Cuối tuần nào cũng có chỗ đang vui, chỉ là bạn chưa biết thôi.',s:'Xem trang tin của tỉnh, thành bạn ở hoặc các nhóm Facebook địa phương, chọn một sự kiện cuối tuần này.',p:180,k:1,ai:'abyg',o:'o',g:'sct',m:'cbhl',d:3,x:'cuoituan'},
{id:194,c:'au',t:'Nấu một gói mì “nâng cấp”',n:'Một gói mì thêm trứng, rau và chút sáng tạo là thành món mới.',s:'Nấu mì như thường, thêm trứng chần, rau cải, ít hành phi, có phô mai thì thả một lát.',p:15,k:0,ai:'ay',o:'i',g:'sctk',m:'cbm',d:1},
{id:195,c:'gt',t:'Nghe nhạc sống ở một quán acoustic',n:'Một giọng hát mộc giữa phố đêm, nghe xong lòng nhẹ hẳn.',s:'Tìm quán có đêm nhạc acoustic tối nay gần bạn, đặt bàn trước và đi cùng một người.',p:120,k:2,ai:'aby',o:'o',g:'t',m:'bxl',d:2},
{id:196,c:'kn',t:'Rủ đồng nghiệp ăn trưa ở một quán mới',n:'Đổi quán ăn trưa, câu chuyện cũng đổi theo.',s:'Hỏi 2–3 đồng nghiệp đi ăn ở một quán chưa ai đến, ai trả phần nấy cho thoải mái.',p:60,k:1,ai:'b',o:'o',g:'c',m:'cl',d:2},
{id:197,c:'gt',t:'Chơi UNO, tiến lên hoặc cờ cá ngựa với cả nhà',n:'Trò chơi cũ kỹ nhưng tiếng cười thì mới nguyên.',s:'Lục tìm bộ bài hoặc bàn cờ trong nhà, rủ mọi người sau bữa tối, ai thua thì rửa bát.',p:45,k:0,ai:'bg',o:'i',g:'tk',m:'cbl',d:1},
{id:198,c:'st',t:'Tô một bức tranh tô màu theo số',n:'Không cần biết vẽ, tô theo số vẫn ra một bức tranh treo được.',s:'Mua một bộ tranh tô màu theo số cỡ nhỏ, trải giấy báo, mở nhạc và tô từ màu đậm trước.',p:120,k:1,ai:'aby',o:'i',g:'ctk',m:'bmx',d:2},
{id:199,c:'gt',t:'Chơi phòng thoát hiểm cùng hội bạn',n:'Một tiếng bị khóa trong phòng, bạn sẽ biết ai trong nhóm bình tĩnh nhất.',s:'Tìm phòng chơi thoát hiểm gần bạn, rủ 3–5 người, đặt lịch trước và chọn chủ đề vừa sức.',p:90,k:2,ai:'b',o:'o',g:'ct',m:'ch',d:4},
// —— Bổ sung tháng 10/2026: vận động
{id:200,c:'vd',t:'Đi bộ nhanh 20 phút sau bữa tối',n:'Hai mươi phút dạo bước sau bữa ăn, bụng nhẹ và đầu óc thư thái.',s:'Đi giày thể thao, chọn một vòng quanh khu nhà có đèn sáng, giữ nhịp đi nhanh vừa đủ để vẫn nói chuyện được.',p:20,k:0,ai:'abyg',o:'o',g:'t',m:'cbmx',d:2},
{id:201,c:'vd',t:'Leo cầu thang bộ 10 tầng',n:'Cầu thang là phòng tập miễn phí ngay trong tòa nhà của bạn.',s:'Leo chậm từng tầng, tay vịn lan can, mệt thì nghỉ ở chiếu nghỉ rồi đi tiếp; đi xuống bằng thang máy cho đỡ mỏi gối.',p:15,k:0,ai:'a',o:'b',g:'sct',m:'cx',d:4,ch:1},
{id:202,c:'vd',t:'Tập plank 3 hiệp, mỗi hiệp 30 giây',n:'Ba mươi giây run run, bụng chắc hơn từng ngày.',s:'Trải thảm, chống khuỷu tay ngay dưới vai, giữ lưng thẳng 30 giây, nghỉ 1 phút rồi lặp lại đủ 3 lần.',p:10,k:0,ai:'a',o:'i',g:'sctk',m:'cx',d:3,ch:1},
{id:203,c:'vd',t:'Đạp xe 30 phút buổi sáng',n:'Gió sớm, đường vắng, một ngày bắt đầu bằng hai bánh xe.',s:'Kiểm tra phanh và lốp, đội mũ bảo hiểm, chọn cung đường ít xe quanh công viên hoặc đường nội khu.',p:30,k:0,ai:'aby',o:'o',g:'s',m:'cbx',d:4},
{id:204,c:'vd',t:'Nhảy dây 300 cái',n:'Món đồ chơi tuổi thơ hóa ra là bài tập tim mạch rất tốt.',s:'Tìm một sợi dây nhảy, chia làm 6 lần mỗi lần 50 cái, nghỉ giữa các lần và nhảy trên nền phẳng.',p:15,k:1,ai:'abg',o:'b',g:'sct',m:'ch',d:4,ch:1},
{id:205,c:'vd',t:'Tập thử một bài khí công hoặc Thái Cực Quyền cơ bản',n:'Chậm mà chắc, từng động tác kéo hơi thở dài ra.',s:'Tìm video bài cơ bản cho người mới, tập theo 15 phút ở chỗ thoáng, làm chậm và thở đều.',p:20,k:0,ai:'ag',o:'b',g:'sc',m:'mx',d:2},
{id:206,c:'vd',t:'Đánh một trận bóng rổ 3 người',n:'Ba người, một rổ, mồ hôi và tiếng cười.',s:'Nhắn nhóm bạn hẹn sân bóng rổ ở công viên hoặc trường gần nhà, mang nước và khởi động kỹ cổ chân.',p:60,k:0,ai:'b',o:'o',g:'ct',m:'ch',d:5},
{id:207,c:'vd',t:'Giãn cơ 10 phút trước khi ngủ',n:'Cơ thể được duỗi ra thì giấc ngủ cũng đến dễ hơn.',s:'Tắt bớt đèn, mở một video giãn cơ trước khi ngủ, làm chậm từng động tác và thở đều.',p:10,k:0,ai:'a',o:'i',g:'tk',m:'bmx',d:1},
{id:208,c:'vd',t:'Đi bộ đến chỗ làm hoặc trường một lần',n:'Con đường quen nhìn từ vỉa hè sẽ khác hẳn khi ngồi trên xe.',s:'Xem bản đồ, nếu dưới 3 km thì xuất phát sớm hơn 30 phút và đi bộ trên vỉa hè thay vì đi xe.',p:40,k:0,ai:'a',o:'o',g:'s',m:'cx',d:4},
{id:209,c:'vd',t:'Tập 50 cái squat chia làm 5 hiệp',n:'Đôi chân khỏe là nền móng cho mọi chuyến đi.',s:'Đứng rộng bằng vai, hạ hông như ngồi xuống ghế, giữ lưng thẳng, mỗi hiệp 10 cái và nghỉ 1 phút.',p:10,k:0,ai:'a',o:'i',g:'sct',m:'cx',d:3,ch:1},
{id:210,c:'vd',t:'Thử một buổi Zumba hoặc Aerobic',n:'Nhạc sôi động, bước nhảy đơn giản, ai cũng theo được.',s:'Tìm lớp gần nhà hoặc một video 20 phút cho người mới, mặc đồ thoải mái và bật nhạc to.',p:30,k:1,ai:'abg',o:'b',g:'sct',m:'cbh',d:3},
{id:211,c:'vd',t:'Đi bộ đường dài 10 km cùng bạn',n:'Mười cây số, đủ để kể cho nhau nghe mọi chuyện.',s:'Chọn cung đường quen có vỉa hè hoặc đường mòn dễ đi, mang nước, mũ, kem chống nắng và đi từ sáng sớm.',p:150,k:0,ai:'by',o:'o',g:'s',m:'ch',d:7,x:'cuoituan'},
// —— Bổ sung: khám phá
{id:212,c:'kp',t:'Đi hết một tuyến buýt hoặc tàu điện bạn chưa đi',n:'Ngồi bên cửa sổ, thành phố tự kể chuyện của nó.',s:'Chọn một tuyến mới, tra giờ chạy, ngồi hết tuyến rồi xuống một ga lạ đi dạo 20 phút trước khi về.',p:90,k:1,ai:'aby',o:'o',g:'sc',m:'cbl',d:3},
{id:213,c:'kp',t:'Ghé một hiệu sách cũ',n:'Mỗi cuốn sách cũ từng có một chủ nhân và một câu chuyện riêng.',s:'Tìm hiệu sách cũ gần bạn, dành 30 phút lục từng kệ và chọn một cuốn dưới 50 nghìn.',p:60,k:1,ai:'ay',o:'o',g:'sct',m:'cbl',d:2},
{id:214,c:'kp',t:'Tìm hiểu lịch sử ngôi đình, ngôi chùa nơi bạn ở',n:'Nơi bạn sống có một lịch sử dài hơn bạn tưởng.',s:'Đến đình hoặc chùa gần nhà, đọc bảng giới thiệu và lễ phép hỏi chuyện người trông coi.',p:60,k:0,ai:'ag',o:'o',g:'sc',m:'cl',d:3},
{id:215,c:'kp',t:'Đi chợ hoa hoặc vườn hoa buổi sáng',n:'Một bó hoa nhỏ đủ làm sáng cả căn phòng một tuần.',s:'Tra chợ hoa hoặc vườn hoa gần bạn, đi buổi sáng khi hoa còn tươi và mua một bó nhỏ mang về.',p:60,k:1,ai:'abyg',o:'o',g:'s',m:'cbl',d:2,x:'cuoituan'},
{id:216,c:'kp',t:'Ăn thử đặc sản của một vùng miền khác',n:'Một món ăn lạ là một chuyến du lịch không cần vé.',s:'Tìm quán đặc sản Tây Bắc, Tây Nguyên hay miền Tây gần bạn và gọi một món bạn chưa nghe tên bao giờ.',p:60,k:2,ai:'abyg',o:'o',g:'ct',m:'ch',d:3},
{id:217,c:'kp',t:'Tham quan một trang trại hoặc xưởng sản xuất mở cửa',n:'Tận mắt xem thứ mình ăn, mình dùng mỗi ngày được làm ra thế nào.',s:'Tìm vườn trái cây, trang trại hay xưởng có tour tham quan gần bạn và gọi đặt lịch trước.',p:180,k:2,ai:'abyg',o:'o',g:'sc',m:'ch',d:5,x:'cuoituan'},
{id:218,c:'kp',t:'Vẽ bản đồ khu phố của bạn',n:'Bạn sẽ ngạc nhiên vì những ngóc ngách mình chưa từng để ý.',s:'Đi bộ một vòng quanh nhà, ghi lại quán quen, cây to, góc đẹp, rồi vẽ lên một tờ giấy A4.',p:60,k:0,ai:'ag',o:'b',g:'sc',m:'cl',d:3},
{id:219,c:'kp',t:'Dậy sớm xem một chợ đầu mối hoạt động',n:'Khi thành phố còn ngủ, chợ đầu mối đã nhộn nhịp từ lâu.',s:'Tìm chợ đầu mối rau, hoa hoặc hải sản gần bạn, rủ một người đi cùng lúc 4–5 giờ sáng, mặc đồ gọn và giữ đồ cẩn thận.',p:90,k:1,ai:'by',o:'o',g:'s',m:'ch',d:6},
{id:220,c:'kp',t:'Ngắm một bức tranh ở bảo tàng mỹ thuật trong 10 phút',n:'Ngắm lâu một bức tranh, bạn sẽ thấy những điều người lướt qua bỏ lỡ.',s:'Đến bảo tàng gần nhất, đi một vòng rồi quay lại bức bạn thích nhất, ngồi ngắm và ghi lại cảm nghĩ.',p:90,k:1,ai:'ay',o:'o',g:'sc',m:'cbxl',d:3},
// —— Bổ sung: sáng tạo
{id:221,c:'st',t:'Làm một bức tranh từ lá khô và hoa ép',n:'Thiên nhiên đã chuẩn bị sẵn màu, bạn chỉ cần sắp xếp.',s:'Nhặt vài chiếc lá, cánh hoa, ép giữa hai trang sách nặng, rồi dán lên giấy bìa thành một bức tranh.',p:60,k:0,ai:'ag',o:'b',g:'sc',m:'cbx',d:3},
{id:222,c:'st',t:'Viết một bài thơ lục bát 8 câu',n:'Sáu tám nhịp nhàng, chuyện hôm nay thành thơ.',s:'Chọn một chủ đề nhỏ như cốc cà phê hay con mèo, viết 4 cặp câu lục bát rồi đọc to để chỉnh vần.',p:30,k:0,ai:'a',o:'b',g:'sctk',m:'cbl',d:4,ch:1},
{id:223,c:'st',t:'Chụp ảnh một món ăn đẹp như tạp chí',n:'Ánh sáng cửa sổ và một chiếc khăn là đủ để món ăn thành ngôi sao.',s:'Đặt món ăn gần cửa sổ, chụp từ trên xuống và chụp ngang, thử 10 góc rồi chọn tấm đẹp nhất.',p:30,k:0,ai:'ay',o:'i',g:'sct',m:'ch',d:2,ch:1},
{id:224,c:'st',t:'Gấp 10 con hạc giấy',n:'Từng nếp gấp tỉ mỉ, đầu óc cũng chậm lại.',s:'Cắt giấy thành hình vuông, xem video gấp hạc cho người mới, gấp con đầu thật chậm rồi nhanh dần.',p:30,k:0,ai:'ag',o:'i',g:'sctk',m:'bmx',d:2,ch:1},
{id:225,c:'st',t:'Thiết kế một chiếc logo cho chính mình',n:'Nếu bạn là một thương hiệu, bạn sẽ trông thế nào?',s:'Viết chữ cái đầu tên bạn, phác 5 kiểu trên giấy, chọn kiểu đẹp nhất rồi vẽ lại trên Canva hoặc điện thoại.',p:45,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:4,ch:1},
{id:226,c:'st',t:'Làm một chiếc kẹp đánh dấu sách handmade',n:'Món quà nhỏ xíu mà người đọc sách nào cũng quý.',s:'Cắt giấy bìa dài 15 cm, vẽ hoặc dán trang trí, đục lỗ ở đầu và buộc một sợi len màu.',p:30,k:0,ai:'ag',o:'i',g:'sctk',m:'cbx',d:2},
{id:227,c:'st',t:'Sáng tác một giai điệu 15 giây trên điện thoại',n:'Ai cũng có một bài hát trong đầu, chỉ là chưa bật ra.',s:'Mở một ứng dụng làm nhạc như GarageBand hoặc BandLab, chọn một nhạc cụ, ghép thử 4 hợp âm và ngân nga theo.',p:45,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:5},
{id:228,c:'st',t:'Trang trí lại bàn học hoặc bàn làm việc',n:'Bàn gọn, đẹp thì làm gì cũng vào hơn.',s:'Dọn hết đồ xuống, lau sạch, chỉ đặt lại những thứ dùng hằng ngày và thêm một chậu cây nhỏ.',p:45,k:1,ai:'a',o:'i',g:'sct',m:'cbx',d:2,ch:1},
{id:229,c:'st',t:'Làm một video stop-motion 10 giây',n:'Vài món đồ vật biết đi là có ngay một bộ phim nhỏ.',s:'Dựng điện thoại cố định, chụp 50 tấm, mỗi tấm dịch đồ vật một chút, rồi ghép bằng ứng dụng stop motion.',p:60,k:0,ai:'abg',o:'i',g:'sct',m:'ch',d:5},
// —— Bổ sung: học hỏi
{id:230,c:'hh',t:'Học cách đọc nhãn dinh dưỡng trên đồ ăn',n:'Đọc nhanh một cái nhãn giúp bạn chọn đồ ăn tốt hơn mỗi lần đi chợ.',s:'Lấy 3 món trong bếp, xem năng lượng, đường, muối trên 100 g và so sánh chúng với nhau.',p:20,k:0,ai:'ag',o:'i',g:'sct',m:'c',d:2,ch:1},
{id:231,c:'hh',t:'Học 5 phím tắt máy tính giúp làm nhanh gấp đôi',n:'Vài tổ hợp phím tiết kiệm cho bạn hàng giờ mỗi tháng.',s:'Học Ctrl+Shift+T, Win+V, Alt+Tab, Win+Shift+S và Ctrl+L, tập mỗi phím 5 lần cho quen tay.',p:20,k:0,ai:'a',o:'i',g:'sctk',m:'c',d:2,ch:1},
{id:232,c:'hh',t:'Tập nhận biết tin giả trên mạng',n:'Một phút kiểm chứng giúp bạn không vô tình chia sẻ tin sai.',s:'Chọn một tin đang lan truyền, tìm nguồn gốc, so với 2 trang báo chính thống và xem kỹ ngày đăng.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'c',d:3,ch:1},
{id:233,c:'hh',t:'Nhờ AI tóm tắt một tài liệu dài rồi tự kiểm lại',n:'Đọc ít hơn mà hiểu nhiều hơn, nếu biết hỏi đúng.',s:'Chọn một bài viết dài, nhờ AI tóm tắt 5 ý, rồi đọc lại bài gốc để kiểm xem AI có bỏ sót hay nói sai gì không.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'c',d:3,ch:1},
{id:234,c:'hh',t:'Học thuộc một bài thơ hay',n:'Thuộc một bài thơ là mang theo một khu vườn nhỏ trong đầu.',s:'Chọn bài thơ bạn thích của một nhà thơ Việt Nam, đọc to 5 lần, chép tay một lần rồi thử đọc không nhìn.',p:30,k:0,ai:'a',o:'b',g:'sctk',m:'cbl',d:3,ch:1},
{id:235,c:'hh',t:'Tìm hiểu tên 10 loài cây quanh nơi bạn sống',n:'Cây nào cũng có tên, biết tên rồi thì thấy thân hơn.',s:'Mở ứng dụng nhận diện cây như Google Lens, đi một vòng quanh nhà, chụp và ghi lại tên 10 loài cây.',p:40,k:0,ai:'ag',o:'o',g:'sc',m:'cbx',d:2},
{id:236,c:'hh',t:'Kẻ bảng theo dõi 3 thói quen trong tuần',n:'Thói quen tốt bắt đầu từ việc thấy mình đã làm được bao nhiêu ngày.',s:'Kẻ một bảng 7 cột cho 7 ngày, ghi 3 thói quen muốn tập, tối nào làm được thì đánh dấu.',p:20,k:0,ai:'a',o:'i',g:'sctk',m:'cx',d:2,ch:1},
{id:237,c:'hh',t:'Nghe một bài giảng mở của trường đại học',n:'Kiến thức của giảng đường giờ chỉ cách bạn một cú bấm.',s:'Tìm bài giảng mở về chủ đề bạn tò mò trên YouTube hoặc Coursera, nghe trọn 1 bài và ghi 3 ý chính.',p:60,k:0,ai:'a',o:'i',g:'sctk',m:'c',d:4,ch:1},
{id:238,c:'hh',t:'Học sơ cứu khi bị bỏng nhẹ, ong đốt, côn trùng cắn',n:'Biết sơ cứu đúng là giúp được mình và người bên cạnh.',s:'Xem hướng dẫn của Hội Chữ thập đỏ hoặc bệnh viện uy tín, ghi lại các bước và kiểm tra tủ thuốc gia đình.',p:30,k:0,ai:'ag',o:'i',g:'sctk',m:'c',d:2,ch:1},
{id:239,c:'hh',t:'Học viết email công việc rõ ràng, lịch sự',n:'Một email rõ ràng giúp bạn được nhớ đến vì sự chỉn chu.',s:'Viết lại một email gần đây theo khung: tiêu đề rõ, lời chào, mục đích, việc cần làm, hạn chót, lời cảm ơn.',p:30,k:0,ai:'a',o:'i',g:'sct',m:'c',d:3,ch:1},
{id:241,c:'hh',t:'Học một việc sửa chữa nhỏ trong nhà',n:'Siết lại bản lề, thay vòi sen, thông bồn rửa: nhỏ mà có võ.',s:'Chọn một việc an toàn như siết bản lề hay thay vòi sen, xem video hướng dẫn và chuẩn bị đúng dụng cụ. Việc dính đến điện thì để thợ làm.',p:45,k:1,ai:'ag',o:'i',g:'sc',m:'cx',d:4},
{id:242,c:'hh',t:'Luyện phát âm tiếng Anh qua một bài hát',n:'Hát theo là cách học phát âm vui nhất.',s:'Chọn một bài hát tiếng Anh chậm, mở lời bài hát, hát theo từng câu và ghi âm lại để nghe.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:3,ch:1},
// —— Bổ sung: sự nghiệp, tiền bạc
{id:240,c:'sn',t:'Tự tính lại lương thực nhận của mình',n:'Hiểu bảng lương của mình là bước đầu để quản lý tiền tốt hơn.',s:'Lấy phiếu lương gần nhất, tra các khoản bảo hiểm, thuế thu nhập cá nhân và tự tính lại xem có khớp không.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'c',d:3,ch:1},
{id:243,c:'sn',t:'Làm một trang tổng hợp những việc bạn đã làm được',n:'Thứ bạn đã làm được chính là tấm danh thiếp tốt nhất.',s:'Gom ảnh hoặc đường link 5 việc bạn tự hào nhất, viết 2 dòng cho mỗi việc vào một file hoặc trang Notion.',p:60,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:5},
{id:244,c:'sn',t:'Ghi lại các khoản trả góp và lên lịch trả',n:'Nhìn rõ con số là bớt lo một nửa.',s:'Liệt kê các khoản đang trả góp hoặc đang nợ: số tiền, lãi, hạn trả, rồi xếp ưu tiên trả khoản lãi cao trước.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'x',d:4},
{id:245,c:'sn',t:'Chuẩn bị 3 câu để trao đổi về lương',n:'Hỏi đúng cách không làm mất lòng ai, còn làm bạn được tôn trọng.',s:'Tìm hiểu mức lương thị trường cho vị trí của bạn, viết sẵn 3 câu nói lịch sự và tập nói trước gương.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:5},
{id:246,c:'sn',t:'Dọn máy tính: xếp file vào thư mục',n:'Máy gọn thì đầu cũng gọn.',s:'Tạo 5 thư mục chính như Công việc, Học, Cá nhân, Ảnh, Lưu trữ, rồi kéo hết file trên màn hình vào đúng chỗ.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'cx',d:2,ch:1},
{id:247,c:'sn',t:'Đặt lệnh tự động để dành tiền mỗi tháng',n:'Tiết kiệm dễ nhất là khi bạn không phải nhớ.',s:'Chọn một mục tiêu như quỹ dự phòng, đặt lệnh chuyển một khoản nhỏ cố định sang tài khoản tiết kiệm ngay sau ngày nhận lương.',p:20,k:0,ai:'a',o:'i',g:'sct',m:'cx',d:3},
{id:248,c:'sn',t:'Học một công cụ mới cho công việc trong 30 phút',n:'Ba mươi phút hôm nay có thể tiết kiệm cho bạn cả trăm giờ sau này.',s:'Chọn một công cụ như Canva, Notion, Google Sheets hay CapCut, làm theo bài hướng dẫn đầu tiên và tự làm một sản phẩm nhỏ.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'c',d:3,ch:1},
{id:249,c:'sn',t:'Viết một bài chia sẻ kinh nghiệm nghề nghiệp',n:'Điều bạn thấy bình thường có thể là bài học quý với người mới vào nghề.',s:'Viết 300 chữ về một bài học bạn rút ra trong công việc và đăng lên LinkedIn hoặc nhóm nghề nghiệp.',p:45,k:0,ai:'a',o:'i',g:'sctk',m:'ch',d:5},
{id:250,c:'sn',t:'Lên lịch 3 việc quan trọng nhất cho ngày mai',n:'Biết sáng mai làm gì, tối nay ngủ ngon hơn.',s:'Viết ra 3 việc quan trọng nhất, gắn giờ cụ thể cho từng việc vào lịch và để việc khó nhất vào buổi sáng.',p:10,k:0,ai:'a',o:'i',g:'tk',m:'mx',d:1},
{id:251,c:'sn',t:'Tham gia một hội thảo hoặc buổi gặp gỡ trong ngành',n:'Một cuộc trò chuyện đúng người có thể mở ra cả một cánh cửa.',s:'Tìm sự kiện miễn phí hoặc giá rẻ trong tháng này, đăng ký, chuẩn bị lời giới thiệu 30 giây và đặt mục tiêu làm quen 3 người.',p:180,k:1,ai:'a',o:'o',g:'ct',m:'ch',d:6},
// —— Bổ sung: sống tử tế
{id:252,c:'tt',t:'Cho mượn một cuốn sách bạn thích',n:'Cuốn sách hay nên được đi nhiều nơi.',s:'Chọn một cuốn sách bạn thích, cho một người bạn mượn và hẹn một buổi cà phê để kể cho nhau nghe đoạn mình thích nhất.',p:15,k:0,ai:'b',o:'b',g:'sct',m:'cl',d:1,ch:1},
{id:253,c:'tt',t:'Để ý giúp một người lớn tuổi hôm nay',n:'Một cánh tay đỡ đúng lúc là món quà lớn.',s:'Khi ra đường, để ý người cần giúp như xách đồ, hỏi đường, nhường chỗ ngồi, và chủ động hỏi: “Cháu giúp được gì không ạ?”.',p:15,k:0,ai:'a',o:'o',g:'sc',m:'cbl',d:2},
{id:254,c:'tt',t:'Làm tình nguyện ở một nhóm cứu hộ chó mèo',n:'Một buổi dắt chó đi dạo cũng là một buổi chữa lành cho chính bạn.',s:'Tìm nhóm cứu hộ chó mèo uy tín gần bạn, hỏi lịch nhận tình nguyện viên dắt chó đi dạo, tắm hoặc dọn chuồng.',p:120,k:0,ai:'ab',o:'o',g:'sc',m:'cbl',d:4,x:'cuoituan'},
{id:255,c:'tt',t:'Góp một suất cơm cho người khó khăn',n:'Một suất cơm có thể là bữa no nhất trong ngày của ai đó.',s:'Tìm quán cơm 0 đồng hoặc nhóm thiện nguyện uy tín gần bạn, hỏi cách góp suất cơm hoặc đến phụ một buổi.',p:30,k:1,ai:'abg',o:'b',g:'sc',m:'cbl',d:3},
{id:256,c:'tt',t:'Viết lời nhắn động viên dán ở nơi công cộng',n:'Một mảnh giấy “Hôm nay bạn đã cố gắng rồi” có thể làm ai đó mỉm cười.',s:'Viết 5 lời nhắn tích cực lên giấy nhớ, dán ở bảng tin chung cư, văn phòng hoặc thư viện, ở những chỗ được phép.',p:20,k:0,ai:'a',o:'b',g:'sct',m:'cbl',d:2,ch:1},
{id:257,c:'tt',t:'Phân loại rác ở nhà trong một tuần',n:'Rác được phân loại đúng là bớt một phần gánh nặng cho đất.',s:'Chuẩn bị 3 túi: giấy, nhựa và kim loại, rác còn lại; dán nhãn và hướng dẫn cả nhà cùng làm.',p:20,k:0,ai:'ag',o:'i',g:'sct',m:'c',d:3,ch:1},
{id:258,c:'tt',t:'Mang bình nước và túi vải khi ra ngoài',n:'Bớt một chai nhựa mỗi ngày, cộng lại là cả một ngọn núi.',s:'Rửa sạch một bình nước, gấp một túi vải nhỏ để sẵn trong túi xách hoặc cốp xe ngay bây giờ.',p:5,k:0,ai:'a',o:'b',g:'sct',m:'c',d:1,ch:1},
{id:259,c:'tt',t:'Chỉ người thân cách dùng ví điện tử an toàn',n:'Một lời nhắc đúng lúc giúp người thân tránh bị lừa.',s:'Ngồi cùng bố mẹ hoặc ông bà, chỉ cách bật khóa vân tay, không bấm link lạ và không đọc mã OTP cho bất kỳ ai.',p:30,k:0,ai:'g',o:'i',g:'sct',m:'cl',d:2},
{id:260,c:'tt',t:'Khen cụ thể một đồng nghiệp trước cả nhóm',n:'Lời khen đúng lúc trước tập thể làm người ta nhớ mãi.',s:'Chọn một việc tốt đồng nghiệp đã làm gần đây và nói rõ việc đó giúp gì cho nhóm trong buổi họp hoặc nhóm chat chung.',p:5,k:0,ai:'b',o:'b',g:'sc',m:'cl',d:2},
{id:261,c:'tt',t:'Trồng một cây xanh',n:'Người trồng cây hôm nay, người sau có bóng mát.',s:'Hỏi tổ dân phố hoặc nhóm môi trường về chỗ được phép trồng, hoặc trồng một cây nhỏ trong chậu ở nhà.',p:60,k:1,ai:'abyg',o:'o',g:'s',m:'cbl',d:4,x:'xuan'},
{id:262,c:'tt',t:'Dọn sạch một góc chung trong xóm hoặc chung cư',n:'Góc chung sạch đẹp là niềm vui của cả xóm.',s:'Rủ một hai người hàng xóm, mang chổi và bao rác, dọn sạch một góc cầu thang, sân hoặc lối đi chung.',p:45,k:0,ai:'abg',o:'o',g:'s',m:'cl',d:4,x:'cuoituan'},
{id:263,c:'tt',t:'Góp đồ dùng học tập cho trẻ em vùng khó khăn',n:'Một chiếc cặp mới có thể là động lực đến trường của một em nhỏ.',s:'Tìm chương trình quyên góp uy tín của trường, Đoàn hoặc báo chí, gom bút vở còn mới và gửi theo hướng dẫn.',p:60,k:1,ai:'abg',o:'b',g:'sc',m:'cbl',d:3},
// —— Bổ sung: chăm mình
{id:264,c:'cm',t:'Uống một cốc nước ấm ngay khi thức dậy',n:'Một cốc nước ấm đánh thức cơ thể nhẹ nhàng nhất.',s:'Để sẵn một cốc ở đầu giường tối nay, sáng mai uống chậm trước khi cầm điện thoại.',p:5,k:0,ai:'a',o:'i',g:'sk',m:'bmx',d:1},
{id:265,c:'cm',t:'Viết ra 5 điều bạn quý ở chính mình',n:'Bạn xứng đáng được chính mình khen.',s:'Ngồi yên 5 phút, viết 5 điều bạn quý ở bản thân, từ nhỏ như nụ cười đến lớn như sự kiên nhẫn.',p:10,k:0,ai:'a',o:'i',g:'sctk',m:'bml',d:2,ch:1},
{id:266,c:'cm',t:'Tắt thông báo mạng xã hội trong 24 giờ',n:'Không còn tiếng ting ting, đầu óc dễ thở hơn hẳn.',s:'Vào cài đặt điện thoại, tắt thông báo của 3 ứng dụng hay làm bạn xao nhãng nhất đến giờ này ngày mai.',p:5,k:0,ai:'a',o:'b',g:'sctk',m:'mx',d:3,ch:1},
{id:267,c:'cm',t:'Ngồi nghe tiếng mưa 10 phút',n:'Tiếng mưa là bản nhạc thư giãn có sẵn của đất trời.',s:'Pha một cốc trà nóng, ngồi cạnh cửa sổ hoặc mở âm thanh mưa, tắt màn hình và chỉ lắng nghe.',p:10,k:0,ai:'ay',o:'i',g:'sctk',m:'bmx',d:1,x:'he thu'},
{id:268,c:'cm',t:'Dọn tủ quần áo, giữ lại những gì bạn thực sự mặc',n:'Tủ đồ nhẹ đi, sáng nào chọn đồ cũng nhanh hơn.',s:'Lấy hết đồ ra, chia 3 đống: giữ, cho tặng, bỏ; món nào cả năm chưa mặc thì cho vào đống tặng.',p:60,k:0,ai:'a',o:'i',g:'sc',m:'cx',d:4},
{id:269,c:'cm',t:'Một buổi tối không màn hình sau 21 giờ',n:'Màn hình tắt sớm, giấc ngủ đến sâu hơn.',s:'Đặt chuông 21 giờ, cất điện thoại và tắt tivi, thay bằng đọc sách giấy, trò chuyện hoặc giãn cơ nhẹ.',p:90,k:0,ai:'ayg',o:'i',g:'t',m:'bmx',d:4},
{id:270,c:'cm',t:'Đi bộ chánh niệm 15 phút',n:'Mỗi bước chân chậm rãi là một hơi thở trở về hiện tại.',s:'Chọn một lối đi yên tĩnh, bước thật chậm, để ý cảm giác bàn chân chạm đất và hơi thở của mình.',p:15,k:0,ai:'a',o:'b',g:'sc',m:'bmx',d:2},
{id:271,c:'cm',t:'Tự nấu một bữa có đủ rau, đạm và tinh bột',n:'Một bữa ăn cân bằng là cách tự chăm mình dễ nhất.',s:'Chia đĩa làm 4: nửa đĩa rau, một phần tư thịt cá hoặc đậu, một phần tư cơm; chọn món đơn giản bạn biết nấu.',p:45,k:1,ai:'ayg',o:'i',g:'ct',m:'bm',d:3},
{id:272,c:'cm',t:'Làm một “hộp niềm vui” cho những ngày buồn',n:'Để dành những thứ nhỏ làm bạn vui, mở ra vào ngày cần.',s:'Tìm một chiếc hộp, bỏ vào thiệp cũ, ảnh in, vé xem phim, lời nhắn dễ thương, rồi ghi nhãn “Mở khi buồn”.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'bl',d:2,ch:1},
{id:273,c:'cm',t:'Đặt lịch cắt tóc hoặc chăm sóc da',n:'Chăm chút cho vẻ ngoài một chút, tinh thần cũng tươi theo.',s:'Gọi tiệm quen hoặc tìm tiệm gần bạn có đánh giá tốt, đặt lịch vào cuối tuần này.',p:60,k:2,ai:'a',o:'o',g:'sc',m:'bmx',d:2,x:'cuoituan'},
// —— Bổ sung: ăn uống
{id:274,c:'au',t:'Tự làm sữa chua tại nhà',n:'Một hũ sữa chua tự làm, chua dịu và an tâm.',s:'Pha sữa tươi ấm với sữa đặc, thêm một hũ sữa chua làm men, chia vào hũ sạch và ủ ấm 6–8 tiếng.',p:30,k:1,ai:'ag',o:'i',g:'sct',m:'cx',d:3},
{id:275,c:'au',t:'Nấu một nồi canh của vùng miền khác',n:'Bát canh quê người kể chuyện về một vùng đất.',s:'Chọn một món như canh chua cá lóc, canh bầu nấu tôm hay canh cua rau đay, xem công thức và đi chợ mua đủ nguyên liệu.',p:60,k:1,ai:'ayg',o:'i',g:'ct',m:'cl',d:4},
{id:276,c:'au',t:'Bày một đĩa trái cây thật đẹp',n:'Cùng là trái cây, bày khéo thì ai cũng muốn ăn.',s:'Chọn 3 loại quả nhiều màu, cắt miếng vừa ăn, xếp lên đĩa theo vòng tròn hoặc hình bông hoa.',p:20,k:1,ai:'ayg',o:'i',g:'sct',m:'cb',d:2,ch:1},
{id:277,c:'au',t:'Học pha cà phê phin đúng kiểu',n:'Tiếng tí tách của phin là nhịp chậm đẹp nhất buổi sáng.',s:'Tráng phin bằng nước sôi, cho 2 thìa cà phê, nén nhẹ, chế ít nước ủ 30 giây rồi chế đầy và đậy nắp.',p:15,k:1,ai:'a',o:'i',g:'sc',m:'cm',d:2},
{id:278,c:'au',t:'Tự làm một hũ dưa góp hoặc kim chi',n:'Một hũ đồ chua tự làm, ăn kèm món gì cũng ngon.',s:'Mua su hào, cà rốt hoặc cải thảo, làm theo một công thức đơn giản và tráng sạch hũ thủy tinh trước khi đựng.',p:60,k:1,ai:'ag',o:'i',g:'sc',m:'cx',d:4},
{id:279,c:'au',t:'Làm bánh mì sandwich mang đi picnic',n:'Bánh tự làm, ngồi bãi cỏ ăn ngon gấp đôi.',s:'Chuẩn bị bánh mì sandwich, trứng, rau, giăm bông hoặc phô mai, kẹp thành 4 phần và bọc giấy sáp.',p:30,k:1,ai:'abyg',o:'i',g:'s',m:'ch',d:2},
{id:280,c:'au',t:'Thử nặn bánh bao hoặc bánh trôi',n:'Nặn bánh cùng nhau, chuyện cũng tròn như những chiếc bánh.',s:'Chọn một món, mua bột pha sẵn và nhân, xem video hướng dẫn rồi rủ người nhà nặn cùng.',p:90,k:1,ai:'ayg',o:'i',g:'sc',m:'cl',d:5},
{id:281,c:'au',t:'Nấu một món chỉ với 3 nguyên liệu',n:'Ít nguyên liệu, nhiều sáng tạo.',s:'Chọn đúng 3 nguyên liệu có sẵn cộng gia vị cơ bản, tự nghĩ ra một món và đặt cho nó một cái tên.',p:40,k:0,ai:'ayg',o:'i',g:'sct',m:'ch',d:4,ch:1},
// —— Bổ sung: giải trí
{id:282,c:'gt',t:'Giải một ô sudoku hoặc ô chữ',n:'Mười lăm phút căng não theo cách vui nhất.',s:'In hoặc mở một ô sudoku mức dễ, hẹn giờ 15 phút và thử giải không dùng gợi ý.',p:15,k:0,ai:'a',o:'b',g:'sctk',m:'cmx',d:2,ch:1},
{id:283,c:'gt',t:'Nghe một truyện ngắn dạng sách nói',n:'Nhắm mắt lại, câu chuyện tự vẽ ra trong đầu.',s:'Mở một ứng dụng sách nói, chọn một truyện ngắn dưới 30 phút và nghe trong lúc nằm thư giãn.',p:30,k:0,ai:'a',o:'i',g:'sctk',m:'bml',d:1},
{id:284,c:'gt',t:'Xem múa rối nước hoặc một buổi diễn truyền thống',n:'Nghệ thuật dân gian vẫn làm khán giả trẻ trầm trồ.',s:'Tìm nhà hát múa rối, chèo, cải lương hoặc ca trù gần bạn và đặt vé suất gần nhất.',p:90,k:2,ai:'abyg',o:'o',g:'ct',m:'cbl',d:3},
{id:285,c:'gt',t:'Tổ chức một cuộc thi nấu ăn mini với bạn bè',n:'Bếp nhỏ, giám khảo là bạn thân, giải thưởng là tiếng cười.',s:'Rủ 2–3 người, mỗi người nấu một món trong 30 phút với cùng một nguyên liệu chính rồi chấm điểm cho nhau.',p:120,k:2,ai:'b',o:'i',g:'ct',m:'ch',d:5,x:'cuoituan'},
{id:286,c:'gt',t:'Chơi đố vui về kỷ niệm gia đình',n:'Câu hỏi về chính gia đình mình mới là khó nhất.',s:'Viết 10 câu hỏi về kỷ niệm của cả nhà, chia đội và chơi sau bữa tối.',p:45,k:0,ai:'g',o:'i',g:'t',m:'cl',d:2},
{id:287,c:'gt',t:'Xem một bộ phim Việt Nam được khen nhiều',n:'Câu chuyện gần gũi làm mình thấy thương nơi mình sống hơn.',s:'Tìm danh sách phim Việt được đánh giá cao vài năm gần đây, chọn một phim và xem trọn không tua.',p:120,k:1,ai:'abyg',o:'i',g:'tk',m:'cbl',d:1},
{id:288,c:'gt',t:'Chơi bóng bàn hoặc bi lắc với bạn',n:'Mấy hiệp đấu nhanh là đủ cười cả buổi.',s:'Tìm câu lạc bộ, nhà văn hóa hoặc quán có bàn bóng bàn, bi lắc, rủ một người và đấu 5 hiệp.',p:60,k:1,ai:'by',o:'o',g:'ct',m:'ch',d:3},
{id:289,c:'gt',t:'Nghe lại những bài hát hồi đi học',n:'Một giai điệu cũ đưa bạn về đúng những năm tháng ấy.',s:'Lập danh sách 10 bài bạn hay nghe hồi đi học, đeo tai nghe và kể lại một kỷ niệm cho một người bạn cũ.',p:40,k:0,ai:'ab',o:'b',g:'sctk',m:'bl',d:1,ch:1},
{id:290,c:'gt',t:'Đi xem một buổi chiếu phim ngoài trời hoặc cà phê phim',n:'Xem phim dưới trời đêm có một cảm giác rất riêng.',s:'Tìm sự kiện chiếu phim ngoài trời, rạp mini hoặc cà phê phim gần bạn, rủ bạn bè và đặt chỗ trước.',p:120,k:2,ai:'by',o:'o',g:'t',m:'cbl',d:2},
{id:291,c:'gt',t:'Học một màn ảo thuật đơn giản với bộ bài',n:'Một màn ảo thuật nhỏ làm cả nhóm bạn trầm trồ.',s:'Xem video dạy ảo thuật bài dễ cho người mới, tập 20 lần trước gương rồi diễn cho một người xem.',p:40,k:0,ai:'abg',o:'i',g:'sctk',m:'ch',d:3,ch:1},
// —— Bổ sung: kết nối
{id:292,c:'kn',t:'Gọi điện chúc mừng sinh nhật thay vì nhắn tin',n:'Nghe giọng nói, lời chúc ấm hơn trăm biểu tượng cảm xúc.',s:'Xem lịch sinh nhật bạn bè trong tuần và gọi điện 2 phút cho người có sinh nhật gần nhất.',p:10,k:0,ai:'b',o:'b',g:'sct',m:'cl',d:2,ch:1},
{id:293,c:'kn',t:'Nấu một món mang sang biếu hàng xóm',n:'Bát chè mang sang, tình làng nghĩa xóm đầy thêm.',s:'Nấu dư một phần món bạn làm ngon, đựng vào hộp đẹp và mang sang nhà bên cạnh.',p:45,k:1,ai:'ag',o:'b',g:'ct',m:'cl',d:3},
{id:294,c:'kn',t:'Kể cho một người tin tưởng nghe chuyện bạn đang lo',n:'Nói ra được, nỗi lo đã nhẹ đi một nửa.',s:'Chọn một người bạn tin tưởng, hẹn gặp hoặc gọi điện, bắt đầu bằng câu: “Dạo này mình có chuyện muốn kể”.',p:30,k:0,ai:'byg',o:'b',g:'sct',m:'bxl',d:4},
{id:295,c:'kn',t:'Lập một nhóm nhỏ cùng nhau tập một thói quen',n:'Có người cùng tập, thói quen tốt dễ thành hơn nhiều.',s:'Rủ 2–3 người cùng một mục tiêu như đi bộ, đọc sách hay dậy sớm, lập nhóm chat và mỗi tối báo một dòng.',p:15,k:0,ai:'b',o:'b',g:'sctk',m:'cl',d:3,ch:1},
{id:296,c:'kn',t:'Hỏi ông bà, bố mẹ về món ăn tuổi thơ của họ',n:'Một câu hỏi nhỏ mở ra cả kho chuyện ngày xưa.',s:'Trong bữa cơm, hỏi: “Hồi nhỏ ông bà, bố mẹ thích ăn gì nhất?”, rồi ghi lại một công thức để nấu thử.',p:30,k:0,ai:'g',o:'i',g:'ct',m:'cl',d:2},
{id:297,c:'kn',t:'Cảm ơn người đã giúp bạn trong năm nay',n:'Người giúp bạn có khi không biết họ đã quan trọng thế nào.',s:'Nghĩ đến một người đã giúp bạn trong năm, viết tin nhắn hoặc thiệp kể cụ thể điều họ đã làm.',p:15,k:0,ai:'a',o:'b',g:'sctk',m:'bl',d:2,ch:1},
{id:298,c:'kn',t:'Tổ chức buổi trao đổi đồ cũ với bạn bè',n:'Đồ bạn đã chán có thể là món người khác đang cần.',s:'Rủ 4–5 người, mỗi người mang 3 món còn tốt như quần áo, sách, đồ trang trí, đổi cho nhau và tặng phần còn lại.',p:120,k:0,ai:'b',o:'b',g:'ct',m:'cl',d:4,x:'cuoituan'},
{id:299,c:'kn',t:'Chụp một tấm ảnh gia đình đủ mặt',n:'Ảnh gia đình là thứ càng để lâu càng quý.',s:'Hẹn giờ cả nhà rảnh, chọn góc sáng trong nhà, dựng điện thoại hẹn giờ chụp và in một tấm treo tường.',p:30,k:0,ai:'g',o:'b',g:'ct',m:'cl',d:2}
